358	static int starcos_init(sc_card_t *card)
359	{
360		unsigned int flags;
361		starcos_ex_data *ex_data;
362	
363		ex_data = calloc(1, sizeof(starcos_ex_data));
364		if (ex_data == NULL)
365			return SC_ERROR_OUT_OF_MEMORY;
366	
367		card->name = "STARCOS";
368		card->cla  = 0x00;
369		card->drv_data = (void *)ex_data;
370		ex_data->pin_encoding = PIN_ENCODING_DETERMINE;
371	
372		flags = SC_ALGORITHM_RSA_PAD_PKCS1
373			| SC_ALGORITHM_ONBOARD_KEY_GEN
374			| SC_ALGORITHM_RSA_PAD_ISO9796
375			| SC_ALGORITHM_RSA_HASH_NONE
376			| SC_ALGORITHM_RSA_HASH_SHA1
377			| SC_ALGORITHM_RSA_HASH_MD5
378			| SC_ALGORITHM_RSA_HASH_RIPEMD160
379			| SC_ALGORITHM_RSA_HASH_MD5_SHA1;
380	
381		card->caps = SC_CARD_CAP_RNG;
382	
383		if ( IS_V3x(card) ) {
384	
385			flags |= SC_CARD_FLAG_RNG
386				| SC_ALGORITHM_RSA_HASH_SHA224
387				| SC_ALGORITHM_RSA_HASH_SHA256
388				| SC_ALGORITHM_RSA_HASH_SHA384
389				| SC_ALGORITHM_RSA_HASH_SHA512
390				| SC_ALGORITHM_RSA_PAD_PSS;
391	
392			_sc_card_add_rsa_alg(card, 512, flags, 0x10001);
393			_sc_card_add_rsa_alg(card, 768, flags, 0x10001);
394			_sc_card_add_rsa_alg(card,1024, flags, 0x10001);
395			_sc_card_add_rsa_alg(card,1728, flags, 0x10001);
396			_sc_card_add_rsa_alg(card,1976, flags, 0x10001);
397			_sc_card_add_rsa_alg(card,2048, flags, 0x10001);
398			if ( IS_V34(card) ) {
399				card->name = "STARCOS 3.4";
400				card->caps |= SC_CARD_CAP_ISO7816_PIN_INFO;
401			} else {
402				card->name = "STARCOS 3.5";
403				_sc_card_add_rsa_alg(card,3072, flags, 0x10001);
404			}
405			card->max_send_size = 255;
406			card->max_recv_size = 256;
407		} else {
408			_sc_card_add_rsa_alg(card, 512, flags, 0x10001);
409			_sc_card_add_rsa_alg(card, 768, flags, 0x10001);
410			_sc_card_add_rsa_alg(card,1024, flags, 0x10001);
411	
412			/* we need read_binary&friends with max 128 bytes per read */
413			card->max_send_size = 128;
414			card->max_recv_size = 128;
415		}
416	
417		if (sc_parse_ef_atr(card) == SC_SUCCESS) {
418			size_t max_recv_size = 0;
419			size_t max_send_size = 0;
420	
421			/* Add max. length values from IAS/ECC specific issuer data */
422			if ( card->ef_atr->issuer_data_len >= 4 ) {
423				max_recv_size = bebytes2ushort(card->ef_atr->issuer_data);
424				max_send_size = bebytes2ushort(card->ef_atr->issuer_data + 2);
425			}
426			/* which could be overridden with ISO7816 EF.ATR options, if present */
427			if (card->ef_atr->max_response_apdu > 0) {
428				max_recv_size = card->ef_atr->max_response_apdu;
429			}
430			if (card->ef_atr->max_command_apdu > 0) {
431				max_send_size = card->ef_atr->max_command_apdu;
432			}
433	
434			if ( max_send_size > 256 && max_recv_size > 256 ) {
435				size_t max_recv_size_prev = card->max_recv_size;
436				size_t max_send_size_prev = card->max_send_size;
437				/* allow SC_CARD_CAP_APDU_EXT independent of ef_atr->caps, see IAS/ECC issuer data above */
438				card->caps |= SC_CARD_CAP_APDU_EXT;
439				/* the received data should not exceed max_recv_size including the sw1/sw2 */
440				card->max_recv_size = max_recv_size - 2;
441				/* the sent APDU should not exceed max_send_size including the 4 bytes of the APDU and 2 * 3 bytes Lc/Le */
442				card->max_send_size = max_send_size - 10;
443				/* probe reader for extended APDU support */
444				if ( starcos_probe_reader_for_ext_apdu(card) ) {
445					sc_log(card->ctx, "Successfully probed extended APDU, enabling extended APDU with max send/recv %d/%d",
446						(int)card->max_send_size, (int)card->max_recv_size);
447				} else {
448					card->caps &= ~(SC_CARD_CAP_APDU_EXT);
449					card->max_recv_size = max_recv_size_prev;
450					card->max_send_size = max_send_size_prev;
451					sc_log(card->ctx, "Ext APDU probing failed, the actual reader does not support ext APDU");
452				}
453			}
454		}
455	
456		if ( ex_data->pin_encoding == PIN_ENCODING_DETERMINE ) {
457			// about to determine PIN encoding
458			ex_data->pin_encoding = starcos_determine_pin_encoding(card);
459		}
460	
461		if ( card->type == SC_CARD_TYPE_STARCOS_V3_4 && starcos_has_esign_app(card) ) {
462			card->type = SC_CARD_TYPE_STARCOS_V3_4_ESIGN;
463			sc_log(card->ctx, "Card has eSign app, card type changed to %d", card->type);
464		}
465	
466		return 0;
467	}
