792	static int starcos_select_fid(sc_card_t *card,
793				      unsigned int id_hi, unsigned int id_lo,
794				      sc_file_t **file_out, int is_file)
795	{
796		sc_apdu_t apdu;
797		u8 data[] = {id_hi & 0xff, id_lo & 0xff};
798		u8 resp[SC_MAX_APDU_BUFFER_SIZE];
799		int bIsDF = 0, r;
800		int isFCP = 0;
801		int isMF = 0;
802	
803		/* request FCI to distinguish between EFs and DFs */
804		sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0xA4, 0x00, 0x00);
805		apdu.p2   = 0x00;
806		apdu.resp = (u8*)resp;
807		apdu.resplen = SC_MAX_APDU_BUFFER_SIZE;
808		apdu.le = 256;
809		apdu.lc = 2;
810		apdu.data = (u8*)data;
811		apdu.datalen = 2;
812	
813		if ( IS_V3x(card) ) {
814			if (id_hi == 0x3f && id_lo == 0x0) {
815				apdu.p1 = 0x0;
816				apdu.p2 = 0x0C;
817				apdu.le = 0;
818				apdu.resplen = 0;
819				apdu.resp = NULL;
820				apdu.cse = SC_APDU_CASE_3_SHORT;
821				isMF = 1;
822			} else if (file_out || is_file) {
823				// last component (i.e. file or path)
824				apdu.p1 = 0x2;
825				apdu.p2 = 0x4;
826			} else {
827				// path component
828				apdu.p1 = 0x1;
829				apdu.p2 = 0x0;
830			}
831		}
832	
833		r = sc_transmit_apdu(card, &apdu);
834		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
835	
836		if (apdu.p2 == 0x00 && apdu.sw1 == 0x62 && apdu.sw2 == 0x84 ) {
837			/* no FCI => we have a DF (see comment in process_fci()) */
838			bIsDF = 1;
839			apdu.p2 = 0x0C;
840			apdu.cse = SC_APDU_CASE_3_SHORT;
841			apdu.resplen = 0;
842			apdu.le = 0;
843			r = sc_transmit_apdu(card, &apdu);
844			LOG_TEST_RET(card->ctx, r, "APDU re-transmit failed");
845		} else if ((IS_V3x(card))
846				&& apdu.p2 == 0x4 && apdu.sw1 == 0x6a && apdu.sw2 == 0x82) {
847			/* not a file, could be a path */
848			bIsDF = 1;
849			apdu.p1 = 0x1;
850			apdu.p2 = 0x0;
851			apdu.resplen = sizeof(resp);
852			apdu.le = 256;
853			apdu.lc = 2;
854			r = sc_transmit_apdu(card, &apdu);
855			LOG_TEST_RET(card->ctx, r, "APDU re-transmit failed");
856		} else if (apdu.sw1 == 0x61 || (apdu.sw1 == 0x90 && apdu.sw2 == 0x00 && !isMF)) {
857			/* SELECT returned some data (possible FCI) =>
858			 * try a READ BINARY to see if a EF is selected */
859			sc_apdu_t apdu2;
860			u8 resp2[2];
861			sc_format_apdu(card, &apdu2, SC_APDU_CASE_2_SHORT, 0xB0, 0, 0);
862			apdu2.resp = (u8*)resp2;
863			apdu2.resplen = 2;
864			apdu2.le = 1;
865			apdu2.lc = 0;
866			r = sc_transmit_apdu(card, &apdu2);
867			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
868			if (apdu2.sw1 == 0x69 && apdu2.sw2 == 0x86) {
869				/* no current EF is selected => we have a DF */
870				bIsDF = 1;
871			} else {
872				isFCP = 1;
873			}
874		}
875	
876		if (apdu.sw1 != 0x61 && (apdu.sw1 != 0x90 || apdu.sw2 != 0x00))
877			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
878	
879		/* update cache */
880		if (bIsDF || isMF) {
881			card->cache.current_path.type = SC_PATH_TYPE_PATH;
882			card->cache.current_path.value[0] = 0x3f;
883			card->cache.current_path.value[1] = 0x00;
884			if (id_hi == 0x3f && id_lo == 0x00)
885				card->cache.current_path.len = 2;
886			else {
887				card->cache.current_path.len = 4;
888				card->cache.current_path.value[2] = id_hi;
889				card->cache.current_path.value[3] = id_lo;
890			}
891		}
892	
893		if (file_out) {
894			sc_file_t *file = sc_file_new();
895			if (!file)
896				LOG_FUNC_RETURN(card->ctx, SC_ERROR_OUT_OF_MEMORY);
897			file->id   = (id_hi << 8) + id_lo;
898			file->path = card->cache.current_path;
899	
900			if (bIsDF || isMF) {
901				/* we have a DF */
902				file->type = SC_FILE_TYPE_DF;
903				file->ef_structure = SC_FILE_EF_UNKNOWN;
904				file->size = 0;
905				file->namelen = 0;
906				file->magic = SC_FILE_MAGIC;
907				*file_out = file;
908			} else {
909				/* ok, assume we have a EF */
910				if ( IS_V3x(card) ) {
911					if (isFCP) {
912						r = process_fcp_v3_4(card->ctx, file, apdu.resp,
913								apdu.resplen);
914					} else {
915						r = process_fci_v3_4(card->ctx, file, apdu.resp,
916								apdu.resplen);
917					}
918				} else {
919					r = process_fci(card->ctx, file, apdu.resp,
920							apdu.resplen);
921				}
922				if (r != SC_SUCCESS) {
923					sc_file_free(file);
924					return r;
925				}
926	
927				*file_out = file;
928			}
929		}
930	
931		SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_SUCCESS);
932	}
933	
934	static int starcos_select_file(sc_card_t *card,
935				       const sc_path_t *in_path,
936				       sc_file_t **file_out)
937	{
938		u8 pathbuf[SC_MAX_PATH_SIZE], *path = pathbuf;
939		int    r, pathtype;
940		size_t i, pathlen;
941		char pbuf[SC_MAX_PATH_STRING_SIZE];
942	
943		SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
944	
945		r = sc_path_print(pbuf, sizeof(pbuf), &card->cache.current_path);
946		if (r != SC_SUCCESS)
947			pbuf[0] = '\0';
948	
949		sc_log(card->ctx,
950			 "current path (%s): %s (len: %"SC_FORMAT_LEN_SIZE_T"u)\n",
951			 card->cache.current_path.type == SC_PATH_TYPE_DF_NAME ?
952			 "aid" : "path", pbuf, card->cache.current_path.len);
953	
954		if ( in_path->len > sizeof(pathbuf) ) {
955			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_BUFFER_TOO_SMALL);
956		}
957		memcpy(path, in_path->value, in_path->len);
958		pathlen = in_path->len;
959		pathtype = in_path->type;
960	
961		if (in_path->aid.len) {
962			if (!pathlen) {
963				if ( in_path->aid.len > sizeof(pathbuf) ) {
964					SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_BUFFER_TOO_SMALL);
965				}
966				memcpy(path, in_path->aid.value, in_path->aid.len);
967				pathlen = in_path->aid.len;
968				pathtype = SC_PATH_TYPE_DF_NAME;
969			} else {
970				r = starcos_select_aid(card, in_path->aid.value, in_path->aid.len, NULL);
971				LOG_TEST_RET(card->ctx, r, "Could not select AID!");
972	
973				if (pathtype == SC_PATH_TYPE_DF_NAME) {
974					pathtype = SC_PATH_TYPE_FILE_ID;
975				}
976			}
977		}
978	
979		if (pathtype == SC_PATH_TYPE_FILE_ID)
980		{	/* SELECT EF/DF with ID */
981			/* Select with 2byte File-ID */
982			if (pathlen != 2)
983				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE,SC_ERROR_INVALID_ARGUMENTS);
984			r = starcos_select_fid(card, path[0],
985					path[1], path[0] == 0x3F && path[1] == 0x00 ? NULL : file_out, 1);
986			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
987		}
988		else if (pathtype == SC_PATH_TYPE_DF_NAME)
989		{	/* SELECT DF with AID */
990			/* Select with 1-16byte Application-ID */
991			r = starcos_select_aid(card, pathbuf, pathlen, file_out);
992			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
993		}
994		else if (pathtype == SC_PATH_TYPE_PATH)
995		{
996			u8 n_pathbuf[SC_MAX_PATH_SIZE];
997	
998			/* Select with path (sequence of File-IDs) */
999			/* Starcos (S 2.1 and SPK 2.3) only supports one
1000			 * level of subdirectories, therefore a path is
1001			 * at most 3 FID long (the last one being the FID
1002			 * of a EF) => pathlen must be even and less than 6
1003			 */
1004			if (pathlen%2 != 0 || pathlen > 6 || pathlen <= 0)
1005				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1006			/* if pathlen == 6 then the first FID must be MF (== 3F00) */
1007			if (pathlen == 6 && ( path[0] != 0x3f || path[1] != 0x00 ))
1008				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1009	
1010			if ( IS_V3x(card) ) {
1011				/* unify path (the first FID should be MF) */
1012				if (path[0] != 0x3f || path[1] != 0x00)
1013				{
1014					n_pathbuf[0] = 0x3f;
1015					n_pathbuf[1] = 0x00;
1016					memcpy(n_pathbuf+2, path, pathlen);
1017					path = n_pathbuf;
1018					pathlen += 2;
1019				}
1020			}
1021	
1022			for ( i=0; i<pathlen-2; i+=2 )
1023			{
1024				r = starcos_select_fid(card, path[i], path[i+1], NULL, 0);
1025				LOG_TEST_RET(card->ctx, r, "SELECT FILE (DF-ID) failed");
1026			}
1027			r = starcos_select_fid(card, path[pathlen-2], path[pathlen-1], file_out, 1);
1028			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
1029		}
1030		else
1031			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1032	}
