1045	#define STARCOS_AC_ALWAYS	0x9f
1046	#define STARCOS_AC_NEVER	0x5f
1047	#define STARCOS_PINID2STATE(a)	((((a) & 0x0f) == 0x01) ? ((a) & 0x0f) : (0x0f - ((0x0f & (a)) >> 1)))
1048	
1049	static u8 process_acl_entry(sc_file_t *in, unsigned int method, unsigned int in_def)
1050	{
1051		u8 def = (u8)in_def;
1052		const sc_acl_entry_t *entry = sc_file_get_acl_entry(in, method);
1053		if (!entry)
1054			return def;
1055		else if (entry->method & SC_AC_CHV) {
1056			unsigned int key_ref = entry->key_ref;
1057			if (key_ref == SC_AC_KEY_REF_NONE)
1058				return def;
1059			else if ((key_ref & 0x0f) == 1)
1060				/* SOPIN */
1061				return (key_ref & 0x80 ? 0x10 : 0x00) | 0x01;
1062			else
1063				return (key_ref & 0x80 ? 0x10 : 0x00) | STARCOS_PINID2STATE(key_ref);
1064		} else if (entry->method & SC_AC_NEVER)
1065			return STARCOS_AC_NEVER;
1066		else
1067			return def;
1068	}
