1237	/** starcos_create_df
1238	 * internal function to create a DF
1239	 * \param card pointer to the sc_card structure
1240	 * \param data pointer to a sc_starcos_create_data object
1241	 * \return SC_SUCCESS or error code
1242	 *
1243	 * This functions registers and creates a DF based in the information
1244	 * stored in a sc_starcos_create_data.df data structure. Note: CREATE END must
1245	 * be called separately to activate the ACs.
1246	 */
1247	static int starcos_create_df(sc_card_t *card, sc_starcos_create_data *data)
1248	{
1249		int    r;
1250		size_t len;
1251		sc_apdu_t       apdu;
1252		sc_context_t   *ctx = card->ctx;
1253	
1254		CHECK_NOT_SUPPORTED_V3_4(card);
1255	
1256		sc_log(ctx,  "creating DF\n");
1257		/* first step: REGISTER DF */
1258		sc_log(ctx,  "calling REGISTER DF\n");
1259	
1260		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x52,
1261			       data->data.df.size[0], data->data.df.size[1]);
1262		len  = 3 + data->data.df.header[2];
1263		apdu.cla |= 0x80;
1264		apdu.lc   = len;
1265		apdu.datalen = len;
1266		apdu.data = data->data.df.header;
1267	
1268		r = sc_transmit_apdu(card, &apdu);
1269		LOG_TEST_RET(ctx, r, "APDU transmit failed");
1270		/* second step: CREATE DF */
1271		sc_log(ctx,  "calling CREATE DF\n");
1272	
1273		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xE0, 0x01, 0x00);
1274		apdu.cla |= 0x80;
1275		apdu.lc   = 25;
1276		apdu.datalen = 25;
1277		apdu.data = data->data.df.header;
1278	
1279		r = sc_transmit_apdu(card, &apdu);
1280		LOG_TEST_RET(ctx, r, "APDU transmit failed");
1281		return sc_check_sw(card, apdu.sw1, apdu.sw2);
1282	}
