2044	static int starcos_card_ctl(sc_card_t *card, unsigned long cmd, void *ptr)
2045	{
2046		sc_starcos_create_data *tmp;
2047	
2048		switch (cmd)
2049		{
2050		case SC_CARDCTL_STARCOS_CREATE_FILE:
2051			tmp = (sc_starcos_create_data *) ptr;
2052			if (tmp->type == SC_STARCOS_MF_DATA)
2053				return starcos_create_mf(card, tmp);
2054			else if (tmp->type == SC_STARCOS_DF_DATA)
2055				return starcos_create_df(card, tmp);
2056			else if (tmp->type == SC_STARCOS_EF_DATA)
2057				return starcos_create_ef(card, tmp);
2058			else
2059				return SC_ERROR_INTERNAL;
2060		case SC_CARDCTL_STARCOS_CREATE_END:
2061			return starcos_create_end(card, (sc_file_t *)ptr);
2062		case SC_CARDCTL_STARCOS_WRITE_KEY:
2063			return starcos_write_key(card, (sc_starcos_wkey_data *)ptr);
2064		case SC_CARDCTL_STARCOS_GENERATE_KEY:
2065			return starcos_gen_key(card, (sc_starcos_gen_key_data *)ptr);
2066		case SC_CARDCTL_ERASE_CARD:
2067			return starcos_erase_card(card);
2068		case SC_CARDCTL_GET_SERIALNR:
2069			return starcos_get_serialnr(card, (sc_serial_number_t *)ptr);
2070		default:
2071			return SC_ERROR_NOT_SUPPORTED;
2072		}
2073	}
