140		unsigned int	ssec_initial_value;
141	#endif
142	} starcos_ctrl_ref_template;
143	
144	// tags
145	#define TAG_STARCOS35_PIN_REFERENCE					0x88
146	#define TAG_STARCOS3X_SUPPORTED_SEC_MECHANISMS_tag		0x7B
147	#define TAG_STARCOS3X_CTRL_REF_TEMPLATE				0xA4
148	#define TAG_STARCOS3X_TRANSMISSION_FORMAT			0x89
149	
150	static const char * starcos_ef_pwdd = "3F000015";
151	static const char * starcos_ef_keyd = "3F000013";
152	
153	/**
154	 * Parses supported security mechanisms record data.
155	 * It returns SC_SUCCESS and the ctrl_ref_template structure data on success
156	 */
157	static int starcos_parse_supported_sec_mechanisms(struct sc_card *card, const unsigned char * buf, size_t buflen, starcos_ctrl_ref_template * ctrl_ref_template)
158	{
159		struct sc_context *ctx = card->ctx;
160		const unsigned char *supported_sec_mechanisms_tag = NULL;
161		size_t taglen;
162	
163		LOG_FUNC_CALLED(ctx);
164	
165		supported_sec_mechanisms_tag = sc_asn1_find_tag(ctx, buf, buflen, TAG_STARCOS3X_SUPPORTED_SEC_MECHANISMS_tag, &taglen);
166		if (supported_sec_mechanisms_tag != NULL && taglen >= 1)   {
167			const unsigned char *tx_fmt_tag = NULL;
168			const unsigned char *ctrl_ref_template_tag = NULL;
169			size_t supported_sec_mechanisms_taglen = taglen;
170	
171			// control-reference template is either included in the supported security mechanisms tag or it can be the CRT tag itself (EF.PWDD)
172			ctrl_ref_template_tag = sc_asn1_find_tag(ctx, supported_sec_mechanisms_tag, taglen, TAG_STARCOS3X_CTRL_REF_TEMPLATE, &taglen);
173			if ( ctrl_ref_template_tag == NULL || taglen == 0 ) {
174				ctrl_ref_template_tag = supported_sec_mechanisms_tag;
175				taglen = supported_sec_mechanisms_taglen;
176			}
177	
178			tx_fmt_tag = sc_asn1_find_tag(ctx, ctrl_ref_template_tag, taglen, TAG_STARCOS3X_TRANSMISSION_FORMAT, &taglen);
179			if ( tx_fmt_tag != NULL && taglen >= 1 ) {
180				ctrl_ref_template->transmission_format = *(tx_fmt_tag + 0);
181				LOG_FUNC_RETURN(ctx, SC_SUCCESS);
182			}
183		}
184	
185		LOG_FUNC_RETURN(ctx, SC_ERROR_TEMPLATE_NOT_FOUND);
186	}
187	
188	static int starcos_determine_pin_format34(sc_card_t *card, unsigned int * pin_format)
189	{
190		struct sc_context *ctx = card->ctx;
191		struct sc_path path;
192		struct sc_file *file;
193		unsigned char buf[256];
194		int rv;
195		int retval = SC_SUCCESS;
196		int rec_no=1;
197	
198		LOG_FUNC_CALLED(ctx);
199	
200		sc_format_path(starcos_ef_pwdd, &path);
201		rv = sc_select_file(card, &path, &file);
202		LOG_TEST_RET(ctx, rv, "Cannot select EF.PWDD file");
203	
204		if ( (rv = sc_read_record(card, rec_no, 0, buf, sizeof(buf), SC_RECORD_BY_REC_NR)) > 0 ) {
205			starcos_ctrl_ref_template ctrl_ref_template;
206			memset((void*)&ctrl_ref_template, 0, sizeof(ctrl_ref_template));
207			rv = starcos_parse_supported_sec_mechanisms(card, buf, rv, &ctrl_ref_template);
208			if ( rv == SC_SUCCESS ) {
209				*pin_format = ctrl_ref_template.transmission_format;
210				sc_log(ctx, "Determined StarCOS 3.4 PIN format: 0x%x", *pin_format);
211			} else {
212				sc_log(ctx, "Failed to parse record %d of EF.PWD, err=%d", rec_no, rv);
213				retval = rv;
214			}
215		} else {
216			sc_log(ctx, "Failed to read record %d of EF.PWDD, err=%d", rec_no, rv);
217			retval = rv;
218		}
219	
220		sc_file_free(file);
221		LOG_FUNC_RETURN(ctx, retval);
222	}
223	
224	static int starcos_determine_pin_format35(sc_card_t *card, unsigned int * pin_format)
225	{
226		struct sc_context *ctx = card->ctx;
227		struct sc_path path;
228		struct sc_file *file;
229		unsigned char buf[256];
230		int rv;
231		int retval = SC_ERROR_RECORD_NOT_FOUND;
232		int rec_no=1;
233		starcos_ctrl_ref_template ctrl_ref_template;
234	
235		LOG_FUNC_CALLED(ctx);
236	
237		sc_format_path(starcos_ef_keyd, &path);
238		rv = sc_select_file(card, &path, &file);
239		LOG_TEST_RET(ctx, rv, "Cannot select EF.KEYD file");
240	
241		while ( (rv = sc_read_record(card, rec_no++, 0, buf, sizeof(buf), SC_RECORD_BY_REC_NR)) > 0 ) {
242			if ( buf[0] != TAG_STARCOS35_PIN_REFERENCE ) continue;
243	
244			memset((void*)&ctrl_ref_template, 0, sizeof(ctrl_ref_template));
245			rv = starcos_parse_supported_sec_mechanisms(card, buf, rv, &ctrl_ref_template);
246			if ( rv == SC_SUCCESS ) {
247				*pin_format = ctrl_ref_template.transmission_format;
248				sc_log(ctx, "Determined StarCOS 3.5 PIN format: 0x%x", *pin_format);
249				retval = rv;
250				// assuming that all PINs and PUKs have the same transmission format
251				break;
252			} else {
253				sc_log(ctx, "Failed to parse record %d of EF.KEYD, err=%d", rec_no-1, rv);
254				retval = rv;
255			}
256		}
257	
258		sc_file_free(file);
259		LOG_FUNC_RETURN(ctx, retval);
260	}
261	
262	/**
263	 * Determine v3.x PIN encoding by parsing either
264	 * EF.PWDD (for v3.4) or EF.KEYD (for v3.5)
265	 *
266	 * It returns an OpenSC PIN encoding, using the default value on failure
267	 */
268	static unsigned int starcos_determine_pin_encoding(sc_card_t *card)
269	{
270		unsigned int pin_format = PIN_FORMAT_DEFAULT;
271		unsigned int encoding = PIN_ENCODING_DETERMINE;
272	
273		if ( IS_V34(card) ) {
274			starcos_determine_pin_format34(card, &pin_format);
275		} else if ( IS_V35(card) ) {
276			starcos_determine_pin_format35(card, &pin_format);
277		}
278	
279		switch (pin_format) {
280		case PIN_FORMAT_PW_ASCII:
281		case PIN_FORMAT_ASCII:
282			encoding = SC_PIN_ENCODING_ASCII;
283			break;
284		case PIN_FORMAT_BCD:
285			encoding = SC_PIN_ENCODING_BCD;
286			break;
287		case PIN_FORMAT_F1:
288		case PIN_FORMAT_F2:
289			encoding = SC_PIN_ENCODING_GLP;
290			break;
291		}
292	
293		sc_log(card->ctx, "Determined PIN encoding: %d", encoding);
294		return encoding;
295	}
