1207	/** starcos_create_mf
1208	 * internal function to create the MF
1209	 * \param card pointer to the sc_card structure
1210	 * \param data pointer to a sc_starcos_create_data object
1211	 * \return SC_SUCCESS or error code
1212	 *
1213	 * This function creates the MF based on the information stored
1214	 * in the sc_starcos_create_data.mf structure. Note: CREATE END must be
1215	 * called separately to activate the ACs.
1216	 */
1217	static int starcos_create_mf(sc_card_t *card, sc_starcos_create_data *data)
1218	{
1219		int    r;
1220		sc_apdu_t       apdu;
1221		sc_context_t   *ctx = card->ctx;
1222	
1223		CHECK_NOT_SUPPORTED_V3_4(card);
1224	
1225		sc_log(ctx,  "creating MF \n");
1226		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xE0, 0x00, 0x00);
1227		apdu.cla |= 0x80;
1228		apdu.lc   = 19;
1229		apdu.datalen = 19;
1230		apdu.data = (u8 *) data->data.mf.header;
1231	
1232		r = sc_transmit_apdu(card, &apdu);
1233		LOG_TEST_RET(ctx, r, "APDU transmit failed");
1234		return sc_check_sw(card, apdu.sw1, apdu.sw2);
1235	}
