1314	/** starcos_create_end
1315	 * internal function to activate the ACs
1316	 * \param card pointer to the sc_card structure
1317	 * \param file pointer to a sc_file object
1318	 * \return SC_SUCCESS or error code
1319	 *
1320	 * This function finishes the creation of a DF (or MF) and activates
1321	 * the ACs.
1322	 */
1323	static int starcos_create_end(sc_card_t *card, sc_file_t *file)
1324	{
1325		int r;
1326		u8  fid[2];
1327		sc_apdu_t       apdu;
1328	
1329		if (file->type != SC_FILE_TYPE_DF)
1330			return SC_ERROR_INVALID_ARGUMENTS;
1331	
1332		CHECK_NOT_SUPPORTED_V3_4(card);
1333	
1334		fid[0] = (file->id >> 8) & 0xff;
1335		fid[1] = file->id & 0xff;
1336		sc_format_apdu(card,&apdu,SC_APDU_CASE_3_SHORT, 0xE0, 0x02, 0x00);
1337		apdu.cla |= 0x80;
1338		apdu.lc   = 2;
1339		apdu.datalen = 2;
1340		apdu.data = fid;
1341		r = sc_transmit_apdu(card, &apdu);
1342		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1343		return sc_check_sw(card, apdu.sw1, apdu.sw2);
1344	}
