1387	/** starcos_erase_card
1388	 * internal function to restore the delivery state
1389	 * \param card pointer to the sc_card object
1390	 * \return SC_SUCCESS or error code
1391	 *
1392	 * This function deletes the MF (for 'test cards' only).
1393	 */
1394	static int starcos_erase_card(sc_card_t *card)
1395	{	/* restore the delivery state */
1396		int r;
1397		u8  sbuf[2];
1398		sc_apdu_t apdu = {0};
1399	
1400		sbuf[0] = 0x3f;
1401		sbuf[1] = 0x00;
1402		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xE4, 0x00, 0x00);
1403		apdu.cla |= 0x80;
1404		apdu.lc   = 2;
1405		apdu.datalen = 2;
1406		apdu.data = sbuf;
1407	
1408		r = sc_transmit_apdu(card, &apdu);
1409		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1410		sc_invalidate_cache(card);
1411		if (apdu.sw1 == 0x69 && apdu.sw2 == 0x85)
1412			/* no MF to delete, ignore error */
1413			return SC_SUCCESS;
1414		else return sc_check_sw(card, apdu.sw1, apdu.sw2);
1415	}
1416	
1417	#define STARCOS_WKEY_CSIZE	124
1418	
1419	/** starcos_write_key
1420	 * set key in isf
1421	 * \param card pointer to the sc_card object
1422	 * \param data pointer to a sc_starcos_wkey_data structure
1423	 * \return SC_SUCCESS or error code
1424	 *
1425	 * This function installs a key header in the ISF (based on the
1426	 * information supplied in the sc_starcos_wkey_data structure)
1427	 * and set a supplied key (depending on the mode).
1428	 */
1429	static int starcos_write_key(sc_card_t *card, sc_starcos_wkey_data *data)
1430	{
1431		int       r;
1432		u8        sbuf[SC_MAX_APDU_BUFFER_SIZE];
1433		const u8 *p;
1434		size_t    len = sizeof(sbuf), tlen, offset = 0;
1435		sc_apdu_t       apdu;
1436	
1437		CHECK_NOT_SUPPORTED_V3_4(card);
1438	
1439		if (data->mode == 0) {	/* mode == 0 => install */
1440			/* install key header */
1441			sbuf[0] = 0xc1;	/* key header tag    */
1442			sbuf[1]	= 0x0c;	/* key header length */
1443			memcpy(sbuf + 2, data->key_header, 12);
1444			sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xf4,
1445				       data->mode, 0x00);
1446			apdu.cla |= 0x80;
1447			apdu.lc   = 14;
1448			apdu.datalen = 14;
1449			apdu.data = sbuf;
1450	
1451			r = sc_transmit_apdu(card, &apdu);
1452			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1453			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1454				return sc_check_sw(card, apdu.sw1, apdu.sw2);
1455			if (data->key == NULL)
1456				return SC_SUCCESS;
1457		}
1458	
1459		if (data->key == NULL)
1460			return SC_ERROR_INVALID_ARGUMENTS;
1461	
1462		p    = data->key;
1463		tlen = data->key_len;
1464		while (tlen != 0) {
1465			/* transmit the key in chunks of STARCOS_WKEY_CSIZE bytes */
1466			u8 c_len = tlen < STARCOS_WKEY_CSIZE ? tlen : STARCOS_WKEY_CSIZE;
1467			sbuf[0] = 0xc2;
1468			sbuf[1] = 3 + c_len;
1469			sbuf[2] = data->kid;
1470			sbuf[3] = (offset >> 8) & 0xff;
1471			sbuf[4] = offset & 0xff;
1472			memcpy(sbuf+5, p, c_len);
1473			len = 5 + c_len;
1474			sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xf4, data->mode, 0x00);
1475			apdu.cla    |= 0x80;
1476			apdu.lc      = len;
1477			apdu.datalen = len;
1478			apdu.data    = sbuf;
1479	
1480			r = sc_transmit_apdu(card, &apdu);
1481			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1482			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1483				return sc_check_sw(card, apdu.sw1, apdu.sw2);
1484			offset += c_len;
1485			p      += c_len;
1486			tlen   -= c_len;
1487		}
1488		return SC_SUCCESS;
1489	}
1490	
1491	/** starcos_gen_key
1492	 * generate public key pair
1493	 * \param card pointer to the sc_card object
1494	 * \param data pointer to a sc_starcos_gen_key_data structure
1495	 * \return SC_SUCCESS or error code
1496	 *
1497	 * This function generates a public key pair and stores the created
1498	 * private key in the ISF (specified by the KID).
1499	 */
1500	static int starcos_gen_key(sc_card_t *card, sc_starcos_gen_key_data *data)
1501	{
1502		int	r;
1503		size_t	i, len = data->key_length >> 3;
1504		sc_apdu_t apdu;
1505		u8 rbuf[SC_MAX_APDU_BUFFER_SIZE];
1506		u8 sbuf[2], *p, *q;
1507	
1508		CHECK_NOT_SUPPORTED_V3_4(card);
1509	
1510		/* generate key */
1511		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x46,  0x00,
1512				data->key_id);
1513		apdu.le      = 0;
1514		sbuf[0] = (u8)(data->key_length >> 8);
1515		sbuf[1] = (u8)(data->key_length);
1516		apdu.data    = sbuf;
1517		apdu.lc      = 2;
1518		apdu.datalen = 2;
1519		r = sc_transmit_apdu(card, &apdu);
1520		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1521		if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1522			return sc_check_sw(card, apdu.sw1, apdu.sw2);
1523		/* read public key via READ PUBLIC KEY */
1524		sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0xf0,  0x9c, 0x00);
1525		sbuf[0]      = data->key_id;
1526		apdu.cla    |= 0x80;
1527		apdu.data    = sbuf;
1528		apdu.datalen = 1;
1529		apdu.lc      = 1;
1530		apdu.resp    = rbuf;
1531		apdu.resplen = sizeof(rbuf);
1532		apdu.le      = 256;
1533		r = sc_transmit_apdu(card, &apdu);
1534		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1535		if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1536			return sc_check_sw(card, apdu.sw1, apdu.sw2);
1537	
1538		data->modulus = malloc(len);
1539		if (!data->modulus)
1540			return SC_ERROR_OUT_OF_MEMORY;
1541		p = data->modulus;
1542		/* XXX use tags to find starting position of the modulus */
1543		q = &rbuf[18];
1544		/* LSB to MSB -> MSB to LSB */
1545		for (i = len; i != 0; i--)
1546			*p++ = q[i - 1];
1547	
1548		return SC_SUCCESS;
1549	}
1550	
1551	/** starcos_set_security_env
1552	 * sets the security environment
1553	 * \param card pointer to the sc_card object
1554	 * \param env pointer to a sc_security_env object
1555	 * \param se_num not used here
1556	 * \return SC_SUCCESS on success or an error code
1557	 *
1558	 * This function sets the security environment (using the starcos spk 2.3
1559	 * command MANAGE SECURITY ENVIRONMENT). In case a COMPUTE SIGNATURE
1560	 * operation is requested , this function tries to detect whether
1561	 * COMPUTE SIGNATURE or INTERNAL AUTHENTICATE must be used for signature
1562	 * calculation.
1563	 */
1564	static int starcos_set_security_env(sc_card_t *card,
1565					    const sc_security_env_t *env,
1566					    int se_num)
1567	{
1568		u8              *p, *pp;
1569		int              r, operation = env->operation;
1570		sc_apdu_t   apdu;
1571		u8               sbuf[SC_MAX_APDU_BUFFER_SIZE];
1572		starcos_ex_data *ex_data = (starcos_ex_data *)card->drv_data;
1573	
1574		p     = sbuf;
1575	
1576		if ( IS_V3x(card) ) {
1577			u8 algorithm_supported = (env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PKCS1) ||
1578									(env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PSS);
1579			if (!algorithm_supported ||
1580				!(env->flags & SC_SEC_ENV_KEY_REF_PRESENT) || env->key_ref_len != 1) {
1581				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1582			}
1583	
1584			/* Tag '84' (length 1) denotes key name or key reference */
1585			*p++ = 0x84;
1586			*p++ = 0x01;
1587			if (env->flags & SC_SEC_ENV_FILE_REF_PRESENT) {
1588				*p++ = *env->key_ref | 0x80;
1589			} else {
1590				*p++ = *env->key_ref;
1591			}
1592	
1593			switch (operation) {
1594				case SC_SEC_OPERATION_SIGN:
1595					sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x22, 0x41, 0xB6);
1596	
1597					/* algorithm / cipher selector? */
1598					/* algorithm: 13.23 PKCS#1 signature with RSA (standard) */
1599					/* algorithm: 13.33.30 PKCS#1-PSS signature with SHA-256 */
1600					*p++ = 0x89;
1601					if (env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PSS) {
1602						*p++ = 0x03;
1603						*p++ = 0x13;
1604						*p++ = 0x33;
1605						*p++ = 0x30;
1606					} else {
1607						// fall back, RSA PKCS1 Padding
1608						*p++ = 0x02;
1609						*p++ = 0x13;
1610						*p++ = 0x23;
1611					}
1612					break;
1613	
1614				case SC_SEC_OPERATION_DECIPHER:
1615					sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x22, 0x41, 0xB8);
1616	
1617					/* algorithm / cipher selector? */
1618					/* algorithm: 11.3  Encipherment RSA (standard) */
1619					/* algorithm: 11.31 Encipherment RSA (standard) with PKCS#1 padding */
1620					/* algorithm: 11.32 Encipherment RSA OAEP padding */
1621					*p++ = 0x89;
1622					*p++ = 0x02;
1623					*p++ = 0x11;
1624					if ( IS_V34(card) )
1625						*p++ = 0x30;
1626					else
1627						*p++ = 0x31;
1628					break;
1629	
1630				default:
1631					sc_log(card->ctx,
1632							"not supported for STARCOS 3.4 cards");
1633					return SC_ERROR_NOT_SUPPORTED;
1634			}
1635	
1636			apdu.data    = sbuf;
1637			apdu.datalen = p - sbuf;
1638			apdu.lc      = p - sbuf;
1639			apdu.le      = 0;
1640			r = sc_transmit_apdu(card, &apdu);
1641			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1642			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1643				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
1644	
1645			if ((operation == SC_SEC_OPERATION_SIGN && env->algorithm_flags == SC_ALGORITHM_RSA_PAD_PKCS1_TYPE_01)
1646				|| (operation == SC_SEC_OPERATION_DECIPHER && env->algorithm_flags == SC_ALGORITHM_RSA_PAD_PKCS1_TYPE_02)) {
1647				// input data will be already padded
1648				ex_data->fix_digestInfo = 0;
1649			} else {
1650				ex_data->fix_digestInfo = env->algorithm_flags;
1651			}
1652			ex_data->sec_ops        = SC_SEC_OPERATION_SIGN;
1653			return SC_SUCCESS;
1654		}
1655	
1656		/* copy key reference, if present */
1657		if (env->flags & SC_SEC_ENV_KEY_REF_PRESENT) {
1658			if (env->flags & SC_SEC_ENV_KEY_REF_SYMMETRIC)
1659				*p++ = 0x83;
1660			else
1661				*p++ = 0x84;
1662			*p++ = env->key_ref_len;
1663			memcpy(p, env->key_ref, env->key_ref_len);
1664			p += env->key_ref_len;
1665		}
1666		pp = p;
1667		if (operation == SC_SEC_OPERATION_DECIPHER){
1668			if (env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PKCS1_TYPE_02) {
1669				*p++ = 0x80;
1670				*p++ = 0x01;
1671				*p++ = 0x02;
1672			} else
1673				return SC_ERROR_INVALID_ARGUMENTS;
1674			sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x22, 0x81,
1675			               0xb8);
1676			apdu.data    = sbuf;
1677			apdu.datalen = p - sbuf;
1678			apdu.lc      = p - sbuf;
1679			apdu.le      = 0;
1680			r = sc_transmit_apdu(card, &apdu);
1681			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1682			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1683				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
1684			return SC_SUCCESS;
1685		}
1686		/* try COMPUTE SIGNATURE */
1687		if (operation == SC_SEC_OPERATION_SIGN && (
1688		    env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PKCS1_TYPE_01 ||
1689		    env->algorithm_flags & SC_ALGORITHM_RSA_PAD_ISO9796)) {
1690			if (env->flags & SC_SEC_ENV_ALG_REF_PRESENT) {
1691				*p++ = 0x80;
1692				*p++ = 0x01;
1693				*p++ = env->algorithm_ref & 0xFF;
1694			} else if (env->flags & SC_SEC_ENV_ALG_PRESENT &&
1695			            env->algorithm == SC_ALGORITHM_RSA) {
1696				/* set the method to use based on the algorithm_flags */
1697				*p++ = 0x80;
1698				*p++ = 0x01;
1699				if (env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PKCS1_TYPE_01) {
1700					if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_SHA1)
1701						*p++ = 0x12;
1702					else if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_RIPEMD160)
1703						*p++ = 0x22;
1704					else if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_MD5)
1705						*p++ = 0x32;
1706					else {
1707						/* can't use COMPUTE SIGNATURE =>
1708						 * try INTERNAL AUTHENTICATE */
1709						p = pp;
1710						operation = SC_SEC_OPERATION_AUTHENTICATE;
1711						goto try_authenticate;
1712					}
1713				} else if (env->algorithm_flags & SC_ALGORITHM_RSA_PAD_ISO9796) {
1714					if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_SHA1)
1715						*p++ = 0x11;
1716					else if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_RIPEMD160)
1717						*p++ = 0x21;
1718					else
1719						return SC_ERROR_INVALID_ARGUMENTS;
1720				} else
1721					return SC_ERROR_INVALID_ARGUMENTS;
1722			}
1723			sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x22, 0x41, 0xb6);
1724			apdu.data    = sbuf;
1725			apdu.datalen = p - sbuf;
1726			apdu.lc      = p - sbuf;
1727			apdu.le      = 0;
1728			/* we don't know whether to use
1729			 * COMPUTE SIGNATURE or INTERNAL AUTHENTICATE */
1730			r = sc_transmit_apdu(card, &apdu);
1731			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1732			if (apdu.sw1 == 0x90 && apdu.sw2 == 0x00) {
1733				ex_data->fix_digestInfo = 0;
1734				ex_data->sec_ops        = SC_SEC_OPERATION_SIGN;
1735				return SC_SUCCESS;
1736			}
1737			/* reset pointer */
1738			p = pp;
1739			/* doesn't work => try next op */
1740			operation = SC_SEC_OPERATION_AUTHENTICATE;
1741		}
1742	try_authenticate:
1743		/* try INTERNAL AUTHENTICATE */
1744		if (operation == SC_SEC_OPERATION_AUTHENTICATE &&
1745		    env->algorithm_flags & SC_ALGORITHM_RSA_PAD_PKCS1) {
1746			*p++ = 0x80;
1747			*p++ = 0x01;
1748			*p++ = 0x01;
1749			sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x22, 0x41,
1750			               0xa4);
1751			apdu.data    = sbuf;
1752			apdu.datalen = p - sbuf;
1753			apdu.lc      = p - sbuf;
1754			apdu.le      = 0;
1755			r = sc_transmit_apdu(card, &apdu);
1756			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1757			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1758				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
1759			ex_data->fix_digestInfo = env->algorithm_flags;
1760			ex_data->sec_ops        = SC_SEC_OPERATION_AUTHENTICATE;
1761			return SC_SUCCESS;
1762		}
1763	
1764		return SC_ERROR_INVALID_ARGUMENTS;
1765	}
1766	
1767	static int starcos_compute_signature(sc_card_t *card,
1768					     const u8 * data, size_t datalen,
1769					     u8 * out, size_t outlen)
1770	{
1771		int r;
1772		sc_apdu_t apdu;
1773		u8 rbuf[SC_MAX_APDU_BUFFER_SIZE];
1774		u8 sbuf[SC_MAX_APDU_BUFFER_SIZE];
1775		starcos_ex_data *ex_data = (starcos_ex_data *)card->drv_data;
1776	
1777		if (datalen > SC_MAX_APDU_BUFFER_SIZE)
1778			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1779	
1780		if (ex_data->sec_ops == SC_SEC_OPERATION_SIGN) {
1781			/* compute signature with the COMPUTE SIGNATURE command */
1782	
1783			if ( IS_V3x(card) ) {
1784				size_t tmp_len;
1785	
1786				sc_format_apdu(card, &apdu, SC_APDU_CASE_4, 0x2A,
1787						   0x9E, 0x9A);
1788				apdu.resp = out;
1789				apdu.resplen = outlen;
1790				apdu.le = outlen;
1791				if (ex_data->fix_digestInfo) {
1792					// need to pad data
1793					unsigned int flags = ex_data->fix_digestInfo & SC_ALGORITHM_RSA_HASHES;
1794					if (flags == 0x00) {
1795						flags = SC_ALGORITHM_RSA_HASH_NONE;
1796					}
1797					tmp_len = sizeof(sbuf);
1798					if (ex_data->fix_digestInfo & SC_ALGORITHM_RSA_PAD_PSS) {
1799						r = sc_pkcs1_strip_digest_info_prefix(NULL, data, datalen, sbuf, &tmp_len);
1800					} else {
1801						r = sc_pkcs1_encode(card->ctx, flags, data, datalen, sbuf, &tmp_len, sizeof(sbuf)*8, NULL);
1802					}
1803					LOG_TEST_RET(card->ctx, r, "sc_pkcs1_encode failed");
1804				} else {
1805					memcpy(sbuf, data, datalen);
1806					tmp_len = datalen;
1807				}
1808	
1809				apdu.data = sbuf;
1810				apdu.datalen = tmp_len;
1811				apdu.lc = tmp_len;
1812	
1813				r = sc_transmit_apdu(card, &apdu);
1814				LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1815			} else {
1816				/* set the hash value     */
1817				sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x2A,
1818						   0x90, 0x81);
1819				apdu.resp = rbuf;
1820				apdu.resplen = sizeof(rbuf);
1821				apdu.le = 0;
1822				memcpy(sbuf, data, datalen);
1823				apdu.data = sbuf;
1824				apdu.lc = datalen;
1825				apdu.datalen = datalen;
1826				r = sc_transmit_apdu(card, &apdu);
1827				LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1828				if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
1829					SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE,
1830							   sc_check_sw(card, apdu.sw1, apdu.sw2));
1831	
1832				/* call COMPUTE SIGNATURE */
1833				sc_format_apdu(card, &apdu, SC_APDU_CASE_2_SHORT, 0x2A,
1834						   0x9E, 0x9A);
1835				apdu.resp = rbuf;
1836				apdu.resplen = sizeof(rbuf);
1837				apdu.le = 256;
1838	
1839				apdu.lc = 0;
1840				apdu.datalen = 0;
1841				r = sc_transmit_apdu(card, &apdu);
1842				LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1843			}
1844			if (apdu.sw1 == 0x90 && apdu.sw2 == 0x00) {
1845				size_t len = apdu.resplen > outlen ? outlen : apdu.resplen;
1846				if ( out != apdu.resp ) {
1847					memcpy(out, apdu.resp, len);
1848				}
1849				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, (int)len);
1850			}
1851		} else if (ex_data->sec_ops == SC_SEC_OPERATION_AUTHENTICATE) {
1852			size_t tmp_len;
1853			CHECK_NOT_SUPPORTED_V3_4(card);
1854			/* call INTERNAL AUTHENTICATE */
1855			sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0x88, 0x10, 0x00);
1856			/* fix/create DigestInfo structure (if necessary) */
1857			if (ex_data->fix_digestInfo) {
1858				unsigned int flags = ex_data->fix_digestInfo & SC_ALGORITHM_RSA_HASHES;
1859				if (flags == 0x0)
1860					/* XXX: assume no hash is wanted */
1861					flags = SC_ALGORITHM_RSA_HASH_NONE;
1862				tmp_len = sizeof(sbuf);
1863				r = sc_pkcs1_encode(card->ctx, flags, data, datalen,
1864						sbuf, &tmp_len, sizeof(sbuf)*8, NULL);
1865				if (r < 0)
1866					return r;
1867			} else {
1868				memcpy(sbuf, data, datalen);
1869				tmp_len = datalen;
1870			}
1871			apdu.lc = tmp_len;
1872			apdu.data = sbuf;
1873			apdu.datalen = tmp_len;
1874			apdu.resp = rbuf;
1875			apdu.resplen = sizeof(rbuf);
1876			apdu.le = 256;
1877			r = sc_transmit_apdu(card, &apdu);
1878			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1879			if (apdu.sw1 == 0x90 && apdu.sw2 == 0x00) {
1880				size_t len = apdu.resplen > outlen ? outlen : apdu.resplen;
1881	
1882				memcpy(out, apdu.resp, len);
1883				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, (int)len);
1884			}
1885		} else
1886			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1887	
1888		/* clear old state */
1889		ex_data->sec_ops = 0;
1890		ex_data->fix_digestInfo = 0;
1891	
1892		SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
1893	}
1894	
1895	static int starcos_decipher(struct sc_card *card,
1896			const u8 * crgram, size_t crgram_len,
1897			u8 * out, size_t outlen)
1898	{
1899		int r;
1900		size_t card_max_send_size = card->max_send_size;
1901		size_t reader_max_send_size = card->reader->max_send_size;
1902		size_t card_max_recv_size = card->max_recv_size;
1903		size_t reader_max_recv_size = card->reader->max_recv_size;
1904	
1905		if (sc_get_max_send_size(card) < crgram_len + 1) {
1906			/* Starcos doesn't support chaining for PSO:DEC, so we just _hope_
1907			 * that both, the reader and the card are able to send enough data.
1908			 * (data is prefixed with 1 byte padding content indicator) */
1909			card->max_send_size = crgram_len + 1;
1910			card->reader->max_send_size = crgram_len + 1;
1911		}
1912	
1913		if (sc_get_max_recv_size(card) < outlen) {
1914			/* Starcos doesn't support get response for PSO:DEC, so we just _hope_
1915			 * that both, the reader and the card are able to receive enough data.
1916			 */
1917			if (0 == (card->caps & SC_CARD_CAP_APDU_EXT)
1918					&& outlen > 256) {
1919				card->max_recv_size = 256;
1920				card->reader->max_recv_size = 256;
1921			} else {
1922				card->max_recv_size = outlen;
1923				card->reader->max_recv_size = outlen;
1924			}
1925		}
1926	
1927		if ( IS_V3x(card) ) {
1928			sc_apdu_t apdu;
1929	
1930			u8 *sbuf = malloc(crgram_len + 1);
1931			if (sbuf == NULL)
1932				return SC_ERROR_OUT_OF_MEMORY;
1933	
1934			sc_format_apdu(card, &apdu, SC_APDU_CASE_4, 0x2A, 0x80, 0x86);
1935			apdu.resp    = out;
1936			apdu.resplen = outlen;
1937			apdu.le      = outlen;
1938	
1939			sbuf[0] = 0x81;
1940			memcpy(sbuf + 1, crgram, crgram_len);
1941			apdu.data = sbuf;
1942			apdu.lc = crgram_len + 1;
1943			apdu.datalen = crgram_len + 1;
1944	
1945			r = sc_transmit_apdu(card, &apdu);
1946			sc_mem_clear(sbuf, crgram_len + 1);
1947	
1948			free(sbuf);
1949	
1950			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
1951	
1952			if (apdu.sw1 == 0x90 && apdu.sw2 == 0x00)
1953				r = (int)apdu.resplen;
1954			else
1955				r = sc_check_sw(card, apdu.sw1, apdu.sw2);
1956		} else {
1957			r = iso_ops->decipher(card, crgram, crgram_len, out, outlen);
1958		}
1959	
1960		/* reset whatever we've modified above */
1961		card->max_send_size = card_max_send_size;
1962		card->reader->max_send_size = reader_max_send_size;
1963		card->max_recv_size = card_max_recv_size;
1964		card->reader->max_recv_size = reader_max_recv_size;
1965	
1966		LOG_FUNC_RETURN(card->ctx, r);
1967	}
1968	
1969	static int starcos_check_sw(sc_card_t *card, unsigned int sw1, unsigned int sw2)
1970	{
1971		const int err_count = sizeof(starcos_errors)/sizeof(starcos_errors[0]);
1972		int i;
1973	
1974		sc_log(card->ctx,
1975			"sw1 = 0x%02x, sw2 = 0x%02x\n", sw1, sw2);
1976	
1977		if (sw1 == 0x90)
1978			return SC_SUCCESS;
1979		if (sw1 == 0x63 && (sw2 & ~0x0fU) == 0xc0 )
1980		{
1981			sc_log(card->ctx,  "Verification failed (remaining tries: %d)\n",
1982			(sw2 & 0x0f));
1983			return SC_ERROR_PIN_CODE_INCORRECT;
1984		}
1985	
1986		/* check starcos error messages */
1987		for (i = 0; i < err_count; i++)
1988			if (starcos_errors[i].SWs == ((sw1 << 8) | sw2))
1989			{
1990				sc_log(card->ctx,  "%s\n", starcos_errors[i].errorstr);
1991				return starcos_errors[i].errorno;
1992			}
1993	
1994		/* iso error */
1995		return iso_ops->check_sw(card, sw1, sw2);
1996	}
1997	
1998	static int starcos_get_serialnr(sc_card_t *card, sc_serial_number_t *serial)
1999	{
2000		int r;
2001		u8  rbuf[SC_MAX_APDU_BUFFER_SIZE];
2002		sc_apdu_t apdu;
2003	
2004		if (!serial)
2005			return SC_ERROR_INVALID_ARGUMENTS;
2006	
2007		/* see if we have cached serial number */
2008		if (card->serialnr.len) {
2009			memcpy(serial, &card->serialnr, sizeof(*serial));
2010			return SC_SUCCESS;
2011		}
2012	
2013		if ( IS_V3x(card) ) {
2014			card->serialnr.len = SC_MAX_SERIALNR;
2015			r = sc_parse_ef_gdo(card, card->serialnr.value, &card->serialnr.len, NULL, 0);
2016			if (r < 0) {
2017				card->serialnr.len = 0;
2018				return r;
2019			}
2020		} else {
2021			/* get serial number via GET CARD DATA */
2022			sc_format_apdu(card, &apdu, SC_APDU_CASE_2_SHORT, 0xf6, 0x00, 0x00);
2023			apdu.cla |= 0x80;
2024			apdu.resp = rbuf;
2025			apdu.resplen = sizeof(rbuf);
2026			apdu.le   = 256;
2027			apdu.lc   = 0;
2028			apdu.datalen = 0;
2029			r = sc_transmit_apdu(card, &apdu);
2030			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
2031			if (apdu.sw1 != 0x90 || apdu.sw2 != 0x00)
2032				return SC_ERROR_INTERNAL;
2033			/* cache serial number */
2034			memcpy(card->serialnr.value, apdu.resp, MIN(apdu.resplen, SC_MAX_SERIALNR));
2035			card->serialnr.len = MIN(apdu.resplen, SC_MAX_SERIALNR);
2036		}
2037	
2038		/* copy and return serial number */
2039		memcpy(serial, &card->serialnr, sizeof(*serial));
2040	
2041		return SC_SUCCESS;
2042	}
2043	
2044	static int starcos_card_ctl(sc_card_t *card, unsigned long cmd, void *ptr)
2045	{
2046		sc_starcos_create_data *tmp;
2047	
2048		switch (cmd)
2049		{
2050		case SC_CARDCTL_STARCOS_CREATE_FILE:
2051			tmp = (sc_starcos_create_data *) ptr;
2052			if (tmp->type == SC_STARCOS_MF_DATA)
2053				return starcos_create_mf(card, tmp);
2054			else if (tmp->type == SC_STARCOS_DF_DATA)
2055				return starcos_create_df(card, tmp);
2056			else if (tmp->type == SC_STARCOS_EF_DATA)
2057				return starcos_create_ef(card, tmp);
2058			else
2059				return SC_ERROR_INTERNAL;
2060		case SC_CARDCTL_STARCOS_CREATE_END:
2061			return starcos_create_end(card, (sc_file_t *)ptr);
2062		case SC_CARDCTL_STARCOS_WRITE_KEY:
2063			return starcos_write_key(card, (sc_starcos_wkey_data *)ptr);
2064		case SC_CARDCTL_STARCOS_GENERATE_KEY:
2065			return starcos_gen_key(card, (sc_starcos_gen_key_data *)ptr);
2066		case SC_CARDCTL_ERASE_CARD:
2067			return starcos_erase_card(card);
2068		case SC_CARDCTL_GET_SERIALNR:
2069			return starcos_get_serialnr(card, (sc_serial_number_t *)ptr);
2070		default:
2071			return SC_ERROR_NOT_SUPPORTED;
2072		}
2073	}
2074	
2075	static int starcos_logout_v3_x(sc_card_t *card)
2076	{
2077		return SC_ERROR_NOT_SUPPORTED;
2078	}
2079	
2080	static int starcos_logout(sc_card_t *card)
2081	{
2082		int r;
2083		sc_apdu_t apdu;
2084		const u8 mf_buf[2] = {0x3f, 0x00};
2085	
2086		if ( IS_V3x(card) ) {
2087			return starcos_logout_v3_x(card);
2088		}
2089	
2090		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xA4, 0x00, 0x0C);
2091		apdu.le = 0;
2092		apdu.lc = 2;
2093		apdu.data    = mf_buf;
2094		apdu.datalen = 2;
2095		apdu.resplen = 0;
2096	
2097		r = sc_transmit_apdu(card, &apdu);
2098		LOG_TEST_RET(card->ctx, r, "APDU re-transmit failed");
2099	
2100		if (apdu.sw1 == 0x69 && apdu.sw2 == 0x85)
2101			/* the only possible reason for this error here is, afaik,
2102			 * that no MF exists, but then there's no need to logout
2103			 * => return SC_SUCCESS
2104			 */
2105			return SC_SUCCESS;
2106		return sc_check_sw(card, apdu.sw1, apdu.sw2);
2107	}
2108	
2109	static int starcos_pin_cmd(sc_card_t *card, struct sc_pin_cmd_data *data,
2110				    int *tries_left)
2111	{
2112		int r;
2113	
2114		LOG_FUNC_CALLED(card->ctx);
2115		starcos_ex_data * ex_data = (starcos_ex_data*)card->drv_data;
2116		if ( IS_V3x(card) ) {
2117			data->flags |= SC_PIN_CMD_NEED_PADDING;
2118			data->pin1.encoding = ex_data->pin_encoding;
2119		}
2120		r = iso_ops->pin_cmd(card, data, tries_left);
2121		SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
2122	}
2123	
2124	static struct sc_card_driver * sc_get_driver(void)
2125	{
2126		struct sc_card_driver *iso_drv = sc_get_iso7816_driver();
2127		if (iso_ops == NULL)
2128			iso_ops = iso_drv->ops;
2129	
2130		starcos_ops = *iso_drv->ops;
2131		starcos_ops.match_card = starcos_match_card;
2132		starcos_ops.init   = starcos_init;
2133		starcos_ops.finish = starcos_finish;
2134		starcos_ops.select_file = starcos_select_file;
2135		starcos_ops.get_challenge = starcos_get_challenge;
2136		starcos_ops.check_sw    = starcos_check_sw;
2137		starcos_ops.create_file = starcos_create_file;
2138		starcos_ops.delete_file = NULL;
2139		starcos_ops.set_security_env  = starcos_set_security_env;
2140		starcos_ops.compute_signature = starcos_compute_signature;
2141		starcos_ops.decipher = starcos_decipher;
2142		starcos_ops.card_ctl    = starcos_card_ctl;
2143		starcos_ops.logout      = starcos_logout;
2144		starcos_ops.pin_cmd     = starcos_pin_cmd;
2145	
2146		return &starcos_drv;
2147	}
2148	
2149	struct sc_card_driver * sc_get_starcos_driver(void)
2150	{
2151		return sc_get_driver();
2152	}
