297	/**
298	 * Returns 1 if an extended APDU can be sent to the card
299	 * with the given card reader. Otherwise returns 0.
300	 */
301	static int starcos_probe_reader_for_ext_apdu(sc_card_t * card) {
302		sc_apdu_t apdu;
303		int rv;
304		/* try to read STARCOS3X_PROBE_APDU_LENGTH bytes */
305		u8 data[STARCOS3X_PROBE_APDU_LENGTH];
306	
307		/* Get Data: Get Chip Serial Number */
308		sc_format_apdu(card, &apdu, SC_APDU_CASE_2_EXT, 0xCA, 0x9F, 0x6C);
309		apdu.cla = 0xA0;
310		apdu.resp = data;
311		apdu.resplen = sizeof(data);
312		apdu.le = apdu.resplen;
313		rv = sc_transmit_apdu(card, &apdu);
314		LOG_TEST_RET(card->ctx, rv, "Failed to send Get Data ext. APDU");
315		return (apdu.sw1 == 0x90 && apdu.sw2 == 0x00);
316	}
