35		const uint8_t    *ptr = NULL;
36		uint16_t          ptr_size = 0;
37		u8                files[SC_MAX_EXT_APDU_BUFFER_SIZE];
38		uint8_t           len = 0;
39		u8               *rnd = NULL, *wrap_buf = NULL, *unwrap_buf = NULL;
40		size_t            wrap_buf_len = 0, unwrap_buf_len = 0;
41		int               r = 0;
42	
43	#ifdef FUZZING_ENABLED
44		fclose(stdout);
45	#endif
46	
47		if (size <= sizeof(unsigned long) + 1)
48			return 0;
49	
50		flag = *((unsigned long *) data);
51		len = *(data + sizeof(unsigned long));
52		data += (sizeof(unsigned long) + sizeof(uint8_t));
53		size -= (sizeof(unsigned long) + sizeof(uint8_t));
54	
55		/* Establish context for fuzz app*/
56		sc_establish_context(&ctx, "fuzz");
57		if (!ctx)
58			return 0;
59	
60		if (fuzz_connect_card(ctx, &card, &reader, data, size) != SC_SUCCESS)
61			goto err;
62	
63		/* Wrap & Unwrap*/
64		if (!(wrap_buf = malloc(SC_MAX_APDU_BUFFER_SIZE)))
65			goto err;
66		wrap_buf_len = SC_MAX_APDU_BUFFER_SIZE;
67		sc_wrap(card, NULL, 0, wrap_buf, wrap_buf_len);
68	
69		fuzz_get_chunk(reader, &ptr, &ptr_size);
70		if (!(unwrap_buf = malloc(ptr_size)))
71			goto err;
72		memcpy(unwrap_buf, ptr, ptr_size);
73		unwrap_buf_len = ptr_size;
74		sc_unwrap(card, unwrap_buf, unwrap_buf_len, NULL, 0);
75	
76		/* Write binary  */
77		sc_write_binary(card, 0, ptr, ptr_size, flag);
78	
79		/* Put data */
80		fuzz_get_chunk(reader, &ptr, &ptr_size);
81		sc_put_data(card, (unsigned int)flag, ptr, ptr_size);
82	
83		/* List files */
84		sc_list_files(card, files, sizeof(files));
85	
86		/* Get challenge */
87		rnd = malloc(len);
88		if (rnd == NULL)
89			goto err;
90		if ((r = sc_get_challenge(card, rnd, len)) != SC_SUCCESS)
91			sc_log(ctx, "sc_get_challenge failed with rc = %d", r);
92	
93		/* Append record */
94		sc_append_record(card, ptr, ptr_size, flag);
95	
96	err:
97		free(rnd);
98		free(wrap_buf);
99		free(unwrap_buf);
100		sc_disconnect_card(card);
101		sc_release_context(ctx);
102		return 0;
103	}
