33	int fuzz_profile_load(struct sc_profile *profile, const uint8_t *data, size_t size)
34	{
35	    int rv = 0;
36	    scconf_context	*conf = NULL;
37	    conf = scconf_new(NULL);
38	    if (!conf)
39	        return 0;
40	
41	    if ((rv = scconf_parse_string(conf, (char *)data)) < 0) {
42	        scconf_free(conf);
43	        return rv;
44	    }
45	
46	    rv = process_conf(profile, conf);
47	    scconf_free(conf);
48	    return rv;
49	}
50	
51	void fuzz_pkcs15init_bind(struct sc_card *card, struct sc_profile **result,
52	                          const uint8_t *data, size_t size)
53	{
54	    struct sc_profile *profile = NULL;
55	    const char	      *driver;
56	    struct sc_pkcs15init_operations * (* func)(void) = NULL;
57	    int r = 0;
58	
59	    if (!card || !card->driver || !result)
60	        return;
61	
62	    *result = NULL;
63	
64	    r = sc_pkcs15init_set_lifecycle(card, SC_CARDCTRL_LIFECYCLE_ADMIN);
65	    if (r < 0 && r != SC_ERROR_NOT_SUPPORTED) {
66	        return;
67	    }
68	
69		profile = sc_profile_new();
70	    if (!profile)
71	        return;
72	    profile->card = card;
73	    driver = card->driver->short_name;
74	
75	    for (int i = 0; profile_operations[i].name; i++) {
76			if (!strcasecmp(driver, profile_operations[i].name)) {
77				func = (struct sc_pkcs15init_operations *(*)(void)) profile_operations[i].func;
78				break;
79			}
80		}
81	    if (func) {
82	        profile->ops = func();
83	    } else {
84	        sc_profile_free(profile);
85	        return;
86	    }
87	    profile->name = strdup("Fuzz profile");
88	
89	    r = sc_pkcs15init_read_info(card, profile);
90	    if (r < 0) {
91			sc_profile_free(profile);
92	        return;
93		}
94	
95	    if (fuzz_profile_load(profile, data, size) < 0) {
96	        sc_profile_free(profile);
97	        return;
98	    }
99	
100	    if (sc_profile_finish(profile, NULL) < 0) {
101	        sc_profile_free(profile);
102	        return;
103	    }
104	    *result = profile;
105	}
106	
107	int fuzz_get_reader_data(const uint8_t *from, size_t from_size, const uint8_t **to, size_t *to_size)
108	{
109	    size_t i = 0;
110	    while(i < from_size - 1 && from[i] != '\0')
111	        i++;
112	        
113	    if (from[i] != '\0')
114	        return 0;
115	
116	    *to_size = from_size - (i + 1);
117	    *to = from + (i + 1);
118	    return 1;
119	}
120	
121	void do_init_app(struct sc_profile *profile, struct sc_pkcs15_card *p15card, sc_card_t *card,
122	                 unsigned char *so_pin, unsigned char *so_puk)
123	{
124	    struct sc_pkcs15init_initargs init_args;
125	    sc_pkcs15_auth_info_t         info;
126	    int                           so_puk_disabled = 0;
127	
128	    memset(&init_args, 0, sizeof(init_args));
129	    sc_pkcs15init_get_pin_info(profile, SC_PKCS15INIT_SO_PIN, &info);
130	    if ((info.attrs.pin.flags & SC_PKCS15_PIN_FLAG_UNBLOCK_DISABLED) &&
131	        (info.attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN))
132	        so_puk_disabled = 1;
133	
134	    sc_pkcs15init_get_pin_info(profile, SC_PKCS15INIT_SO_PUK, &info);
135	
136	    init_args.so_pin = so_pin;
137	    init_args.so_pin_len = 8;
138	
139	    if (!so_puk_disabled) {
140	        init_args.so_puk = so_puk;
141	        init_args.so_puk_len = 8;
142	    }
143	
144	    sc_pkcs15init_add_app(card, profile, &init_args);
145	}
146	
147	void do_store_pin(struct sc_profile *profile, struct sc_pkcs15_card *p15card, sc_card_t *card,
148	                  unsigned char *pin, unsigned char *so_pin)
149	{
150	    struct sc_pkcs15init_pinargs pin_args;
151	    char   pin_id[SC_PKCS15_MAX_ID_SIZE] = "1\0";
152	    sc_pkcs15init_set_p15card(profile, p15card);
153	    
154	    memcpy(pin, "1234555678\0", 11); /* Set new pin */
155	    memset(&pin_args, 0, sizeof(pin_args));
156	
157	    sc_pkcs15_format_id(pin_id, &pin_args.auth_id);
158	    pin_args.pin = pin;
159	    pin_args.pin_len = 6;
160	    pin_args.label = "Basic PIN";
161	
162	    pin_args.puk = so_pin;
163	    pin_args.puk_len = 8;
164	
165	    sc_pkcs15init_store_pin(p15card, profile, &pin_args);
166	}
167	
168	void do_store_data_object(struct sc_profile *profile, struct sc_pkcs15_card *p15card, sc_card_t *card,
169	                          uint8_t *buf, size_t len)
170	{
171	    struct sc_pkcs15init_dataargs args;
172	    char value[SC_MAX_OBJECT_ID_OCTETS];
173	
174	    memcpy(value, buf, SC_MAX_OBJECT_ID_OCTETS);
175	    value[len < SC_MAX_OBJECT_ID_OCTETS ? len : SC_MAX_OBJECT_ID_OCTETS - 1] = '\0';
176	
177	    memset(&args, 0, sizeof(args));
178	    sc_init_oid(&args.app_oid);
179	    args.label = "label";
180	    args.app_label = "pkcs15-init";
181	
182	    sc_format_oid(&args.app_oid, value);
183	
184	    args.der_encoded.value = buf;
185	    args.der_encoded.len = len;
186	    sc_pkcs15init_store_data_object(p15card, profile, &args, NULL);
187	}
188	
189	void do_generate_key(struct sc_profile *profile, struct sc_pkcs15_card *p15card, sc_card_t *card)
190	{
191	    struct sc_pkcs15init_keygen_args keygen_args;
192	    int algorithms[] = { SC_ALGORITHM_RSA, SC_ALGORITHM_EC };
193	    unsigned int keybits[] = { 1024, 0 };
194	
195	    memset(&keygen_args, 0, sizeof(keygen_args));
196	    sc_pkcs15_format_id("01", &(keygen_args.prkey_args.auth_id));
197	    keygen_args.prkey_args.access_flags |=
198	                    SC_PKCS15_PRKEY_ACCESS_SENSITIVE
199	                | SC_PKCS15_PRKEY_ACCESS_ALWAYSSENSITIVE
200	                | SC_PKCS15_PRKEY_ACCESS_NEVEREXTRACTABLE
201	                | SC_PKCS15_PRKEY_ACCESS_LOCAL;
202	
203	    for (int i = 0; i < 2; i++) {
204	        keygen_args.prkey_args.key.algorithm = algorithms[i];
205	        if (algorithms[i] == SC_ALGORITHM_EC) /* strdup called also in parse_alg_spec() */
206	            keygen_args.prkey_args.key.u.ec.params.named_curve = strdup("prime256v1");
207	        sc_pkcs15init_generate_key(p15card, profile, &keygen_args, keybits[i], NULL);
208	        if (algorithms[i] == SC_ALGORITHM_EC)
209	            free(keygen_args.prkey_args.key.u.ec.params.named_curve);
210	    }
211	}
212	
213	void do_generate_skey(struct sc_profile *profile, struct sc_pkcs15_card *p15card, sc_card_t *card)
214	{
215	    struct sc_pkcs15init_skeyargs skey_args;
216	    int algorithms[] = { SC_ALGORITHM_DES, SC_ALGORITHM_3DES, SC_ALGORITHM_AES };
217	    unsigned int keybits[] = { 64, 192, 128 };
218	
219	    /* init keygen_args*/
220	    memset(&skey_args, 0, sizeof(skey_args));
221	    skey_args.label = "label";
222	    skey_args.usage |= SC_PKCS15_PRKEY_USAGE_ENCRYPT | SC_PKCS15_PRKEY_USAGE_DECRYPT;
223	    skey_args.user_consent = 0;
224	
225	    for (int i = 0; i < 3; i++) {
226	        skey_args.algorithm = algorithms[i];
227	        skey_args.value_len = keybits[i];
228	        sc_pkcs15init_generate_secret_key(p15card, profile, &skey_args, NULL);
229	    }
230	}
231	
232	void do_store_secret_key(struct sc_profile *profile, struct sc_pkcs15_card *p15card,
233	                         sc_card_t *card, uint8_t *buf)
234	{
235	    struct sc_pkcs15init_skeyargs args;
236	    int algorithms[] = { SC_ALGORITHM_AES, SC_ALGORITHM_DES, SC_ALGORITHM_3DES };
237	    unsigned int keybits[] = { 128, 64, 192 };
238	
239	    memset(&args, 0, sizeof(args));
240	    args.access_flags |= SC_PKCS15_PRKEY_ACCESS_EXTRACTABLE | SC_PKCS15_PRKEY_ACCESS_SENSITIVE;
241	    args.usage |= SC_PKCS15_PRKEY_USAGE_ENCRYPT | SC_PKCS15_PRKEY_USAGE_DECRYPT;
242	    sc_pkcs15_format_id("02", &(args.auth_id));
243	
244	    for (int i = 0; i < 3; i++) {
245	        size_t keybytes = (keybits[i] + 7) / 8;
246	        args.key.data = malloc(keybytes);
247	        memcpy(args.key.data, buf, keybytes);
248	        args.key.data_len = keybytes;
249	        args.algorithm = algorithms[i];
250	        args.value_len = keybits[i];
251	
252	        sc_pkcs15init_store_secret_key(p15card, profile, &args, NULL);
253	        if (args.key.data)
254	            free(args.key.data);
255	    }
256	}
257	
258	void do_erase(struct sc_profile *profile, sc_card_t *card)
259	{
260	    struct sc_pkcs15_card *p15card;
261	
262	    p15card = sc_pkcs15_card_new();
263	    p15card->card = card;
264	
265	    sc_pkcs15init_erase_card(p15card, profile, NULL);
266	    sc_pkcs15_card_free(p15card);
267	}
268	
269	int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
270	{
271	    sc_context_t          *ctx = NULL;
272	    sc_card_t             *card = NULL;
273	    struct sc_pkcs15_card *p15card = NULL;
274	    struct sc_profile     *profile = NULL;
275	    struct sc_reader      *reader = NULL;
276	    const uint8_t         *reader_data = NULL;
277	    size_t                 reader_data_size = 0;
278	    uint8_t               *buf = NULL;
279	    uint16_t               len = size < 256 ? size : 256;
280	    unsigned char         *pin = NULL;
281	    unsigned char         *so_pin = NULL;
282	    unsigned char         *puk = NULL;
283	    unsigned char         *so_puk = NULL;
284	    struct sc_pkcs15_card *tmp_p15_data = NULL;
285	
286	#ifdef FUZZING_ENABLED
287	    fclose(stdout);
288	#endif
289	
290	    if (size == 0)
291	        return 0;
292	
293	    if (!fuzz_get_reader_data(data, size, &reader_data, &reader_data_size)) {
294	        return 0;
295	    }
296	
297	    /* Establish context for fuzz app*/
298	    sc_establish_context(&ctx, "fuzz");
299	    if (!ctx)
300	        return 0;
301	
302	    if (fuzz_connect_card(ctx, &card, &reader, reader_data, reader_data_size) != SC_SUCCESS)
303	        goto end;
304	
305	    /* Load profile and bind with card */
306	    fuzz_pkcs15init_bind(card, &profile, data, size - reader_data_size);
307	
308	    if(!profile)
309	        goto end;
310	
311	    pin = malloc(11);
312	    so_pin = malloc(9);
313	    puk = malloc(9);
314	    so_puk = malloc(9);
315	    buf = malloc(len * sizeof(char));
316	    if (!pin || !so_pin || !puk || !so_puk || !buf)
317	        goto end_release;
318	
319	    memcpy(pin, "123456\0", 7);
320	    memcpy(so_pin, "12345678\0", 9);
321	    memcpy(puk, "12345678\0", 9);
322	    memcpy(so_puk, "12345678\0", 9);
323	    memcpy(buf, data, len);
324	
325	    /* test pkcs15-init functionality*/
326	    do_init_app(profile, p15card, card, so_pin, so_puk);
327	
328	    if (!sc_pkcs15_bind(card, NULL, &p15card)) { /* First and only sc_pkcs15_bind calling, is omitted in next cases*/
329	        do_store_pin(profile, p15card, card, pin, so_pin);
330	    }
331	
332	    /* sc_pkcs15_bind failed, no point in testing next cases */
333	    if (!p15card)
334	        goto end_release;
335	
336	    do_store_data_object(profile, p15card, card, buf, len);
337	    do_generate_key(profile, p15card, card);
338	    do_generate_skey(profile, p15card, card);
339	    do_store_secret_key(profile, p15card, card, buf);
340	
341	    sc_pkcs15init_finalize_card(card, profile);
342	    sc_pkcs15init_sanity_check(p15card, profile);
343	
344	    do_erase(profile, card);
345	
346	end_release:
347	    free(pin);
348	    free(puk);
349	    free(so_pin);
350	    free(so_puk);
351	    free(buf);
352	
353	end:
354		if (profile) {
355			tmp_p15_data = profile->p15_data;
356			sc_pkcs15init_unbind(profile);
357			if (tmp_p15_data != p15card)
358				sc_pkcs15_unbind(tmp_p15_data);
359		}
360		if (p15card) {
361			sc_pkcs15_unbind(p15card);
362		}
363	    if (card)
364		    sc_disconnect_card(card);
365	    sc_release_context(ctx);
366	        
367	    return 0;
368	}
