20	
21	#include "config.h"
22	
23	#include <sys/types.h>
24	#include <stdlib.h>
25	#include <string.h>
26	#include <assert.h>
27	#include <stdarg.h>
28	
29	#include "libopensc/log.h"
30	#include "libopensc/opensc.h"
31	#include "libopensc/cardctl.h"
32	#include "pkcs15-init.h"
33	#include "profile.h"
34	
35	#define STARCOS_AC_NEVER	0x5f
36	#define STARCOS_AC_ALWAYS	0x9f
37	
38	#define STARCOS_SOPIN_GID	0x01
39	#define STARCOS_SOPIN_STATE	0x01
40	#define STARCOS_SOPIN_GAC	0x01
41	#define STARCOS_SOPIN_LID	0x81
42	#define STARCOS_SOPIN_LAC	0x11;
43	
44	static int starcos_finalize_card(sc_card_t *card);
45	
46	static int starcos_erase_card(struct sc_profile *pro, sc_pkcs15_card_t *p15card)
47	{
48		return sc_card_ctl(p15card->card, SC_CARDCTL_ERASE_CARD, NULL);
49	}
50	
51	static u8 get_so_ac(const sc_file_t *file, unsigned int op,
52		const sc_pkcs15_auth_info_t *auth, unsigned int def,
53		unsigned int need_global)
54	{
55		int is_global = 1;
56		const sc_acl_entry_t *acl;
57	
58		if (auth->attrs.pin.flags & SC_PKCS15_PIN_FLAG_LOCAL)
59			is_global = 0;
60		if (!is_global && need_global)
61			return def & 0xff;
62		acl = sc_file_get_acl_entry(file, op);
63		if (acl->method == SC_AC_NONE)
64			return STARCOS_AC_ALWAYS;
65		else if (acl->method == SC_AC_NEVER)
66			return STARCOS_AC_NEVER;
67		else if (acl->method == SC_AC_SYMBOLIC) {
68			if (is_global)
69				return STARCOS_SOPIN_GAC;
70			else
71				return STARCOS_SOPIN_LAC;
72		} else
73			return def;
74	}
75	
76	
77	static int starcos_init_card(sc_profile_t *profile, sc_pkcs15_card_t *p15card)
78	{
79		struct sc_card *card = p15card->card;
80		static const u8 key[]  = {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08};
81		int		ret;
82		sc_starcos_create_data  mf_data, ipf_data;
83		sc_file_t	*mf_file, *isf_file, *ipf_file;
84		sc_path_t	tpath;
85		u8		*p = mf_data.data.mf.header, tmp = 0;
86		sc_pkcs15_auth_info_t sopin = {0};
87	
88		/* test if we already have a MF */
89		memset(&tpath, 0, sizeof(sc_path_t));
90		tpath.value[0] = 0x3f;
91		tpath.value[1] = 0x00;
92		tpath.len      = 2;
93		tpath.type     = SC_PATH_TYPE_PATH;
94		ret = sc_select_file(card, &tpath, NULL);
95		if (ret == SC_SUCCESS)
96			/* we already have a MF => return OK */
97			return ret;
98	
99		sc_profile_get_pin_info(profile, SC_PKCS15INIT_SO_PIN, &sopin);
100	
101		/* get mf profile */
102		ret = sc_profile_get_file(profile, "MF", &mf_file);
103		if (ret < 0)
104			return ret;
105		/* get size of the isf */
106		ret = sc_profile_get_file(profile, "mf_isf", &isf_file);
107		if (ret < 0) {
108			sc_file_free(mf_file);
109			return ret;
110		}
111		mf_data.type = SC_STARCOS_MF_DATA;
112		memcpy(p, key, 8);
113		p   += 8;
114		*p++ = (mf_file->size  >> 8) & 0xff;
115		*p++ = mf_file->size  & 0xff;
116		*p++ = (isf_file->size >> 8) & 0xff;
117		*p++ = isf_file->size & 0xff;
118		/* AC CREATE EF   */
119		*p++ = get_so_ac(mf_file, SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 1);
120		/* AC CREATE KEY  */
121		*p++ = get_so_ac(isf_file, SC_AC_OP_WRITE, &sopin, STARCOS_AC_NEVER,  1);
122		/* AC CREATE DF   */
123		*p++ = get_so_ac(mf_file, SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 1);
124		/* AC REGISTER DF */
125		*p++ = get_so_ac(mf_file, SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 1);
126		*p++ = 0x00;	/* SM CR:  no */
127		*p++ = 0x00;	/* SM EF:  no */
128		*p = 0x00;	/* SM ISF: no */
129		sc_file_free(mf_file);
130		sc_file_free(isf_file);
131		/* call CREATE MF  */
132		ret = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_FILE, &mf_data);
133		if (ret != SC_SUCCESS)
134			return ret;
135		/* create IPF */
136		/* get size of the ipf */
137		ret = sc_profile_get_file(profile, "mf_ipf", &ipf_file);
138		if (ret < 0)
139			return ret;
140		ipf_data.type = SC_STARCOS_EF_DATA;
141		p = ipf_data.data.ef.header;
142		*p++ = (ipf_file->id >> 8) & 0xff;
143		*p++ = ipf_file->id & 0xff;
144		*p++ = STARCOS_AC_ALWAYS;	/* AC READ: always */
145		/* AC WRITE IPF */
146		*p++ = get_so_ac(ipf_file,SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 1);
147		*p++ = STARCOS_AC_NEVER;	/* AC ERASE    */
148		*p++ = STARCOS_AC_NEVER;	/* AC LOCK     */
149		*p++ = STARCOS_AC_NEVER;	/* AC UNLOCK   */
150		*p++ = STARCOS_AC_NEVER;	/* AC INCREASE */
151		*p++ = STARCOS_AC_NEVER;	/* AC_DECREASE */
152		*p++ = STARCOS_AC_NEVER;	/* RFU         */
153		*p++ = STARCOS_AC_NEVER;	/* RFU         */
154		*p++ = 0x00;			/* SM          */
155		*p++ = 0x00;			/* SID         */
156		*p++ = 0xA1;			/* IPF         */
157		*p++ = (ipf_file->size >> 8) & 0xff;
158		*p = ipf_file->size & 0xff;
159		ret  = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_FILE, &ipf_data);
160		if (ret != SC_SUCCESS) {
161			sc_file_free(ipf_file);
162			return ret;
163		}
164		/* init IPF */
165		ret = sc_select_file(card, &ipf_file->path, NULL);
166		sc_file_free(ipf_file);
167		if (ret < 0)
168			return ret;
169		ret = sc_update_binary(card, 0, &tmp, 1, 0);
170		if (ret < 0)
171			return ret;
172		return SC_SUCCESS;
173	}
