792	static int starcos_store_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
793		sc_pkcs15_object_t *obj, sc_pkcs15_prkey_t *key)
794	{
795		int     r;
796		u8	key_buf[STARCOS_MAX_PR_KEYSIZE];
797	
798		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *) obj->data;
799		const sc_acl_entry_t   *acl_entry;
800		sc_file_t              *tfile;
801		struct sc_pkcs15_prkey_rsa *rsa = &key->u.rsa;
802		sc_starcos_wkey_data tkey;
803	
804		if (key->algorithm != SC_ALGORITHM_RSA)
805			/* ignore non-RSA keys */
806			return SC_ERROR_INVALID_ARGUMENTS;
807	
808		/* create sc_starcos_wkey_data */
809		if (starcos_encode_prkey(rsa, key_buf))
810			return SC_ERROR_INTERNAL;
811	
812		/* get and verify sopin if necessary */
813		r = sc_profile_get_file(profile, "p15_isf", &tfile);
814	        if (r < 0)
815	                return r;
816		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
817		if (acl_entry->method  != SC_AC_NONE) {
818			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
819		}
820		sc_file_free(tfile);
821		if (r < 0)
822			return r;
823	
824		tkey.mode    = 0x01;	/* update key */
825		tkey.kid     = (u8) kinfo->key_reference;
826		tkey.key     = key_buf;
827		tkey.key_len = STARCOS_MAX_PR_KEYSIZE;
828	
829		r = sc_card_ctl(p15card->card, SC_CARDCTL_STARCOS_WRITE_KEY, &tkey);
830		if (r != SC_SUCCESS)
831			return r;
832		/* store public key in the IPF */
833		return starcos_write_pukey(profile, p15card->card, rsa, kinfo);
834	}
835	
836	static int starcos_generate_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
837			sc_pkcs15_object_t *obj, sc_pkcs15_pubkey_t *pubkey)
838	{
839		int r;
840		const sc_acl_entry_t   *acl_entry;
841		sc_file_t              *tfile;
842		sc_starcos_gen_key_data	gendat;
843		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *) obj->data;
844	
845		if (obj->type != SC_PKCS15_TYPE_PRKEY_RSA)
846			return SC_ERROR_NOT_SUPPORTED;
847	
848		/* get and verify sopin if necessary */
849		r = sc_profile_get_file(profile, "p15_isf", &tfile);
850	        if (r < 0)
851	                return r;
852		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
853		if (acl_entry->method  != SC_AC_NONE) {
854			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
855		}
856		sc_file_free(tfile);
857		if (r < 0)
858			return r;
859	
860		/* XXX It would be better to write the public key header
861		 * in the IPF when the private key header is created, but
862		 * as we don't know the size of the exponent at this time
863		 * we would waste space.
864		 */
865		/* create (empty) public key entry */
866		r = starcos_write_pukey(profile, p15card->card, NULL, kinfo);
867		if (r < 0)
868			return r;
869		/* generate key pair */
870		gendat.key_id     = (u8) kinfo->key_reference;
871		gendat.key_length = (size_t) kinfo->modulus_length;
872		gendat.modulus    = NULL;
873		r = sc_card_ctl(p15card->card, SC_CARDCTL_STARCOS_GENERATE_KEY, &gendat);
874		if (r != SC_SUCCESS)
875			return r;
876		/* get the modulus via READ PUBLIC KEY */
877		if (pubkey) {
878			u8 *buf;
879			struct sc_pkcs15_pubkey_rsa *rsa = &pubkey->u.rsa;
880			/* set the modulus */
881			rsa->modulus.data = gendat.modulus;
882			rsa->modulus.len  = kinfo->modulus_length >> 3;
883			/* set the exponent (always 0x10001) */
884			buf = malloc(3);
885			if (!buf)
886				return SC_ERROR_OUT_OF_MEMORY;
887			buf[0] = 0x01;
888			buf[1] = 0x00;
889			buf[2] = 0x01;
890			rsa->exponent.data = buf;
891			rsa->exponent.len  = 3;
892	
893			pubkey->algorithm = SC_ALGORITHM_RSA;
894		} else
895			/* free public key */
896			free(gendat.modulus);
897	
898		return SC_SUCCESS;
899	}
900	
901	static int starcos_finalize_card(sc_card_t *card)
902	{
903		int       r;
904		sc_file_t tfile;
905		sc_path_t tpath;
906	
907		/* SELECT FILE MF */
908		sc_format_path("3F00", &tpath);
909		r = sc_select_file(card, &tpath, NULL);
910		if (r < 0)
911			return r;
912	
913		/* call CREATE END for the MF (ignore errors) */
914		tfile.type = SC_FILE_TYPE_DF;
915		tfile.id   = 0x3f00;
916		r = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_END, &tfile);
917		if (r < 0)
918			sc_log(card->ctx,  "failed to call CREATE END for the MF\n");
919		/* call CREATE END for the apps (pkcs15) DF */
920		tfile.type = SC_FILE_TYPE_DF;
921		tfile.id   = 0x5015;
922		r = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_END, &tfile);
923		if (r == SC_ERROR_NOT_ALLOWED)
924			/* card is already finalized */
925			return SC_SUCCESS;
926		return r;
927	}
