184	
185		sc_profile_get_pin_info(profile, SC_PKCS15INIT_SO_PIN, &sopin);
186	
187		/* get p15_isf profile */
188		ret = sc_profile_get_file(profile, "p15_isf", &isf_file);
189		if (ret < 0)
190			return ret;
191	
192		df_data.type = SC_STARCOS_DF_DATA;
193		memset(p, 0, 25);
194		*p++ = (df->id >> 8) & 0xff;
195		*p++ = df->id & 0xff;
196		*p++ = df->namelen & 0xff;
197		memcpy(p, df->name, (u8) df->namelen);
198		p   += 16;
199		*p++ = (isf_file->size >> 8) & 0xff;
200		*p++ = isf_file->size & 0xff;
201		/* AC CREATE EF  */
202		*p++ = get_so_ac(df, SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 0);
203		/* AC CREATE KEY */
204		*p++ = get_so_ac(isf_file, SC_AC_OP_WRITE, &sopin, STARCOS_AC_NEVER, 0);
205		*p++ = 0x00;		/* SM EF:  no */
206		*p = 0x00;		/* SM ISF: no */
207		df_data.data.df.size[0] = (df->size >> 8) & 0xff;
208		df_data.data.df.size[1] = df->size & 0xff;
209		sc_file_free(isf_file);
210		/* call CREATE DF  */
211		ret = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_FILE, &df_data);
212		if (ret != SC_SUCCESS)
213			return ret;
214		/* create IPF */
215		ret = sc_select_file(card, &df->path, NULL);
216		if (ret != SC_SUCCESS)
217			return ret;
218		ret = sc_profile_get_file(profile, "p15_ipf", &ipf_file);
219		if (ret < 0)
220			return ret;
221		ipf_data.type = SC_STARCOS_EF_DATA;
222		p = ipf_data.data.ef.header;
223		*p++ = (ipf_file->id >> 8) & 0xff;
224		*p++ = ipf_file->id & 0xff;
225		*p++ = STARCOS_AC_ALWAYS;	/* AC READ     */
226		/* AC WRITE IPF */
227		*p++ = get_so_ac(ipf_file, SC_AC_OP_CREATE, &sopin, STARCOS_AC_ALWAYS, 0);
228		*p++ = STARCOS_AC_NEVER;	/* AC ERASE    */
229		*p++ = STARCOS_AC_NEVER;	/* AC LOCK     */
230		*p++ = STARCOS_AC_NEVER;	/* AC UNLOCK   */
231		*p++ = STARCOS_AC_NEVER;	/* AC INCREASE */
232		*p++ = STARCOS_AC_NEVER;	/* AC_DECREASE */
233		*p++ = STARCOS_AC_NEVER;	/* RFU         */
234		*p++ = STARCOS_AC_NEVER;	/* RFU         */
235		*p++ = 0x00;			/* SM          */
236		*p++ = 0x00;			/* SID         */
237		*p++ = 0xA1;			/* IPF         */
238		*p++ = (ipf_file->size >> 8) & 0xff;
239		*p = ipf_file->size & 0xff;
240		ret  = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_FILE, &ipf_data);
241		if (ret != SC_SUCCESS) {
242			sc_file_free(ipf_file);
243			return ret;
244		}
245		/* init IPF */
246		ret = sc_select_file(card, &ipf_file->path, NULL);
247		sc_file_free(ipf_file);
248		if (ret < 0)
249			return ret;
250		ret = sc_update_binary(card, 0, &tmp, 1, 0);
251		if (ret < 0)
252			return ret;
253		return SC_SUCCESS;
254	}
