486	/* range of possible key ids for private keys
487	 */
488	#define STARCOS_MIN_LPKEY_ID	0x91
489	#define STARCOS_MAX_LPKEY_ID	0x9f
490	#define STARCOS_MIN_GPKEY_ID	0x11
491	#define STARCOS_MAX_GPKEY_ID	0x1f
492	static int starcos_key_reference(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
493		sc_pkcs15_prkey_info_t *prkey)
494	{
495		/* use (local) KIDs 0x91-0x9f for private rsa keys */
496		if (prkey->key_reference < STARCOS_MIN_LPKEY_ID)
497			prkey->key_reference = STARCOS_MIN_LPKEY_ID;
498		if (prkey->key_reference > STARCOS_MAX_LPKEY_ID)
499			return SC_ERROR_TOO_MANY_OBJECTS;
500		return SC_SUCCESS;
501	}
502	
503	#define STARCOS_MAX_PR_KEYSIZE	370
504	
505	static int starcos_encode_prkey(struct sc_pkcs15_prkey_rsa *rsa, u8 *buf)
506	{
507		size_t	i = 0;
508		u8	*p = buf;
509	
510		/* clear key buffer */
511		memset(buf, 0, STARCOS_MAX_PR_KEYSIZE);
512	
513		if (rsa->p.len && rsa->q.len && rsa->dmp1.len &&
514			rsa->dmq1.len && rsa->iqmp.len) {
515			/* CRT RSA key     */
516			/* get number of 0x00 bytes */
517			i = STARCOS_MAX_PR_KEYSIZE - rsa->p.len - rsa->q.len -
518			    rsa->dmp1.len - rsa->dmq1.len - 45 - rsa->p.len;
519	
520			/* key format list */
521			*p++ = 0x0c;
522			*p++ = 0x91;
523			*p++ = (u8) rsa->p.len;
524			*p++ = 0x92;
525			*p++ = (u8) rsa->q.len;
526			*p++ = 0x94;
527			*p++ = (u8) rsa->dmp1.len + 16;
528			*p++ = 0x95;
529			*p++ = (u8) rsa->dmq1.len + 16;
530			*p++ = 0x97;
531			*p++ = (u8) rsa->p.len;
532			*p++ = 0x00;
533			*p++ = (u8) i;
534			/* copy key components */
535			for (i = rsa->q.len; i != 0; i--)
536				*p++ = rsa->q.data[i - 1];
537			for (i = rsa->p.len; i != 0; i--)
538				*p++ = rsa->p.data[i - 1];
539			for (i = 16; i != 0; i--)
540				*p++ = 0x00;
541			for (i = rsa->dmp1.len; i != 0; i--)
542				*p++ = rsa->dmq1.data[i - 1];
543			for (i = 16; i != 0; i--)
544				*p++ = 0x00;
545			for (i = rsa->dmq1.len; i != 0; i--)
546				*p++ = rsa->dmp1.data[i - 1];
547			for (i = rsa->iqmp.len; i != 0; i--)
548				*p++ = rsa->iqmp.data[i - 1];
549			for (i = rsa->p.len - rsa->iqmp.len; i != 0; i--)
550				*p++ = 0x00;
551		} else if (rsa->modulus.len && rsa->d.len) {
552			/* normal RSA key  */
553			i = STARCOS_MAX_PR_KEYSIZE - 7 - rsa->modulus.len
554	                    - rsa->d.len - 16;
555			/* key format list */
556			*p++ = 6;
557			*p++ = 0x90;
558			*p++ = (u8) rsa->modulus.len;
559			*p++ = 0x93;
560			*p++ = (u8) rsa->d.len + 16;
561			*p++ = 0x00;
562			*p++ = (u8) i;
563			/* copy key components */
564			for (i = rsa->modulus.len; i != 0; i--)
565				*p++ = rsa->modulus.data[i - 1];
566			for (i = 16; i != 0; i--)
567				*p++ = 0x00;
568			for (i = rsa->d.len; i != 0; i--)
569				*p++ = rsa->d.data[i - 1];
570		} else
571			return SC_ERROR_INTERNAL;
572	
573		return SC_SUCCESS;
574	}
575	
576	/* XXX the whole IPF stuff doesn't really work very well */
577	/** starcos_ipf_get_lastpos
578	 * returns the offset to the first byte after the last key
579	 */
580	static size_t starcos_ipf_get_lastpos(u8 *ipf, size_t ipf_len)
581	{
582		size_t	num_keys, tmp;
583		u8	*p = ipf;
584	
585		if (!ipf || ipf_len < 13)
586			return 0;
587		num_keys = *p++; /* the first bytes contains the number of keys*/
588		if (num_keys == 0xff)
589			num_keys = 0;
590		if (!num_keys)
591			return 1;
592		while (num_keys--) {
593			size_t offset = p - ipf;	/* note: p > ipf */
594			/* get offset to the next key header */
595			tmp = 12 + (p[1] << 8) + p[2];
596			if (tmp + offset > ipf_len)
597				return 0;
598			p += tmp;
599		}
600	
601		return p - ipf;
602	}
603	
604	static int starcos_encode_pukey(struct sc_pkcs15_prkey_rsa *rsa, u8 *buf,
605		sc_pkcs15_prkey_info_t *kinfo)
606	{
607		size_t	i = 0;
608		u8	*p = buf;
609	
610		/* if rsa == NULL return key header for key generation    */
611		if (!rsa) {
612			if (!buf)
613				/* if buf == NULL return length of the encoded key */
614				return 12 + (int)(kinfo->modulus_length >> 3);
615			*p++ = 0x06;			/* length key header */
616			*p++ = 0x01; 			/* CHA byte */
617			*p++ = 0x01;
618			*p++ = 0x10;			/* RSA: n   */
619			*p++ = (kinfo->modulus_length >> 3) & 0xff;
620			*p++ = 0x13;			/* RSA: e   */
621			*p++ = 0x04;
622			*p = (u8) kinfo->key_reference;	/* CHA byte */
623		} else {
624			/* encode normal public key  */
625			int	mod_len = (int)rsa->modulus.len  & 0xff,
626				exp_len = (int)rsa->exponent.len & 0xff;
627	
628			if (!buf)
629				return 8 + mod_len + exp_len + 1;
630	
631			*p++ = 0x06;			/* length key header */
632			*p++ = 0x01; 			/* CHA byte */
633			*p++ = 0x01;
634			*p++ = 0x10;			/* RSA: n   */
635			*p++ = mod_len;
636			*p++ = 0x13;			/* RSA: e   */
637			*p++ = exp_len + 1;
638			*p++ = (u8) kinfo->key_reference;	/* CHA byte */
639			/* copy modulus  */
640			for (i = mod_len; i != 0; i--)
641				*p++ = rsa->modulus.data[i - 1];
642			/* copy exponent */
643			for (i = exp_len; i != 0; i--)
644				*p++ = rsa->exponent.data[i - 1];
645			*p = 0x00;
646		}
647		return SC_SUCCESS;
648	}
649	
650	static int starcos_write_pukey(sc_profile_t *profile, sc_card_t *card,
651		 struct sc_pkcs15_prkey_rsa *rsa, sc_pkcs15_prkey_info_t *kinfo)
652	{
653		int		r;
654		size_t		len, keylen, endpos;
655		u8		*buf, key[280], *p, num_keys;
656		sc_file_t	*tfile = NULL;
657		sc_path_t	tpath;
658	
659		/* get ipf profile */
660		tpath = kinfo->path;
661		r = sc_profile_get_file_in(profile, &tpath, "p15_ipf", &tfile);
662		if (r < 0)
663			return r;
664		tpath = tfile->path;
665		sc_file_free(tfile);
666		tfile = NULL;
667		r = sc_select_file(card, &tpath, &tfile);
668		if (r != SC_SUCCESS)
669			/* unable to select ipf */
670			return r;
671		len = tfile->size;
672		sc_file_free(tfile);
673		buf = malloc(len);
674		if (!buf)
675			return SC_ERROR_OUT_OF_MEMORY;
676		/* read the complete IPF */
677		r = sc_read_binary(card, 0, buf, len, 0);
678		if (r < 0 || r != (int)len) {
679			free(buf);
680			return r;
681		}
682		/* get/fix number of keys */
683		num_keys = buf[0];
684		if (num_keys == 0xff)
685			num_keys = 0;
686		/* encode public key */
687		keylen  = starcos_encode_pukey(rsa, NULL, kinfo);
688		if (!keylen) {
689			free(buf);
690			return SC_ERROR_INTERNAL;
691		}
692		p = key;
693		*p++ = (u8) kinfo->key_reference;
694		*p++ = (keylen >> 8) & 0xff;
695		*p++ = keylen & 0xff;
696		*p++ = STARCOS_AC_ALWAYS;	/* AC WRITE etc XXX */
697		*p++ = 0x0f;
698		*p++ = 0;
699		*p++ = 0x09;			/* ALGO XXX */
700		*p++ = 0x4a;			/* AKD  XXX */
701		*p++ = ((keylen >> 8) & 0xff) | 0x80;
702		*p++ = keylen & 0xff;
703		r = starcos_encode_pukey(rsa, p, kinfo);
704		if (r != SC_SUCCESS) {
705			free(buf);
706			return SC_ERROR_INTERNAL;
707		}
708		p   += keylen;
709		*p++ = 0x04;				/* CPI */
710		*p = (u8) kinfo->key_reference;	/* CHA */
711		/* updated IPF (XXX: currently append only) */
712		num_keys++;
713		r = sc_update_binary(card, 0, &num_keys, 1, 0);
714		if (r < 0) {
715			free(buf);
716			return r;
717		}
718		endpos = starcos_ipf_get_lastpos(buf, len);
719		free(buf);
720		return sc_update_binary(card, (unsigned)endpos, key, keylen + 12, 0);
721	}
722	
723	static int starcos_create_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
724		sc_pkcs15_object_t *obj)
725	{
726		struct sc_card *card = p15card->card;
727		int	r, pin_id;
728		u8	akd = 0, state;
729	
730		sc_file_t              *tfile;
731		const sc_acl_entry_t   *acl_entry;
732		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *)obj->data;
733		sc_starcos_wkey_data    tkey;
734	
735		/* get and verify sopin if necessary */
736		r = sc_profile_get_file(profile, "p15_isf", &tfile);
737	        if (r < 0)
738	                return r;
739		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
740		if (acl_entry->method  != SC_AC_NONE) {
741			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
742		}
743		else   {
744			r = sc_select_file(card, &tfile->path, NULL);
745		}
746		sc_file_free(tfile);
747		if (r < 0)
748			return r;
749	
750		/* create sc_starcos_wkey_data */
751		tkey.mode    = 0x00;	/* install new key */
752		tkey.kid     = (u8) kinfo->key_reference;
753		tkey.key_header[0] = (u8) kinfo->key_reference;
754		tkey.key_header[1] = (STARCOS_MAX_PR_KEYSIZE >> 8) & 0xff;
755		tkey.key_header[2] = STARCOS_MAX_PR_KEYSIZE & 0xff;
756	
757		pin_id = sc_pkcs15init_get_pin_reference(p15card, profile, SC_AC_SYMBOLIC,
758				SC_PKCS15INIT_USER_PIN);
759		if (pin_id < 0)
760			state = STARCOS_AC_ALWAYS;
761		else {
762			state  = STARCOS_PINID2STATE(pin_id);	/* get the necessary state */
763			state |= pin_id & 0x80 ? 0x10 : 0x00;	/* local vs. global key id */
764		}
765		tkey.key_header[3] = state;		/* AC to access key        */
766		if (obj->user_consent)
767			tkey.key_header[4] = 0x0f;	/* do state transition */
768		else
769			tkey.key_header[4] = 0x8f;	/* no state transition */
770		tkey.key_header[5] = 0x11; /* require local state == 1 to update key */
771		tkey.key_header[6] = 0x33;
772		tkey.key_header[7] = 0x00;
773		tkey.key_header[8] = 0x09;
774		if (kinfo->usage & SC_PKCS15_PRKEY_USAGE_NONREPUDIATION)
775			akd |= 0x10;
776		if (kinfo->usage & SC_PKCS15_PRKEY_USAGE_SIGN)
777			akd |= 0x31;	/* allow DS, IA and PKCS11 */
778		if (kinfo->usage & SC_PKCS15_PRKEY_USAGE_SIGNRECOVER)
779			akd |= 0x31;	/* allow DS, IA and PKCS11 */
780		if (kinfo->usage & SC_PKCS15_PRKEY_USAGE_DECRYPT ||
781		    kinfo->usage & SC_PKCS15_PRKEY_USAGE_UNWRAP)
782			akd |= 0x02;
783		tkey.key_header[9]  = akd;
784		tkey.key_header[10] = 0x03;
785		tkey.key_header[11] = 0xa0;
786		tkey.key     = NULL;
787		tkey.key_len = 0;
788	
789		return sc_card_ctl(card, SC_CARDCTL_STARCOS_WRITE_KEY, &tkey);
790	}
791	
792	static int starcos_store_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
793		sc_pkcs15_object_t *obj, sc_pkcs15_prkey_t *key)
794	{
795		int     r;
796		u8	key_buf[STARCOS_MAX_PR_KEYSIZE];
797	
798		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *) obj->data;
799		const sc_acl_entry_t   *acl_entry;
800		sc_file_t              *tfile;
801		struct sc_pkcs15_prkey_rsa *rsa = &key->u.rsa;
802		sc_starcos_wkey_data tkey;
803	
804		if (key->algorithm != SC_ALGORITHM_RSA)
805			/* ignore non-RSA keys */
806			return SC_ERROR_INVALID_ARGUMENTS;
807	
808		/* create sc_starcos_wkey_data */
809		if (starcos_encode_prkey(rsa, key_buf))
810			return SC_ERROR_INTERNAL;
811	
812		/* get and verify sopin if necessary */
813		r = sc_profile_get_file(profile, "p15_isf", &tfile);
814	        if (r < 0)
815	                return r;
816		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
817		if (acl_entry->method  != SC_AC_NONE) {
818			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
819		}
820		sc_file_free(tfile);
821		if (r < 0)
822			return r;
823	
824		tkey.mode    = 0x01;	/* update key */
825		tkey.kid     = (u8) kinfo->key_reference;
826		tkey.key     = key_buf;
827		tkey.key_len = STARCOS_MAX_PR_KEYSIZE;
828	
829		r = sc_card_ctl(p15card->card, SC_CARDCTL_STARCOS_WRITE_KEY, &tkey);
830		if (r != SC_SUCCESS)
831			return r;
832		/* store public key in the IPF */
833		return starcos_write_pukey(profile, p15card->card, rsa, kinfo);
834	}
835	
836	static int starcos_generate_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
837			sc_pkcs15_object_t *obj, sc_pkcs15_pubkey_t *pubkey)
838	{
839		int r;
840		const sc_acl_entry_t   *acl_entry;
841		sc_file_t              *tfile;
842		sc_starcos_gen_key_data	gendat;
843		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *) obj->data;
844	
845		if (obj->type != SC_PKCS15_TYPE_PRKEY_RSA)
846			return SC_ERROR_NOT_SUPPORTED;
847	
848		/* get and verify sopin if necessary */
849		r = sc_profile_get_file(profile, "p15_isf", &tfile);
850	        if (r < 0)
851	                return r;
852		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
853		if (acl_entry->method  != SC_AC_NONE) {
854			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
855		}
856		sc_file_free(tfile);
857		if (r < 0)
858			return r;
859	
860		/* XXX It would be better to write the public key header
861		 * in the IPF when the private key header is created, but
862		 * as we don't know the size of the exponent at this time
863		 * we would waste space.
864		 */
865		/* create (empty) public key entry */
866		r = starcos_write_pukey(profile, p15card->card, NULL, kinfo);
867		if (r < 0)
868			return r;
869		/* generate key pair */
870		gendat.key_id     = (u8) kinfo->key_reference;
871		gendat.key_length = (size_t) kinfo->modulus_length;
872		gendat.modulus    = NULL;
873		r = sc_card_ctl(p15card->card, SC_CARDCTL_STARCOS_GENERATE_KEY, &gendat);
874		if (r != SC_SUCCESS)
875			return r;
876		/* get the modulus via READ PUBLIC KEY */
877		if (pubkey) {
878			u8 *buf;
879			struct sc_pkcs15_pubkey_rsa *rsa = &pubkey->u.rsa;
880			/* set the modulus */
881			rsa->modulus.data = gendat.modulus;
882			rsa->modulus.len  = kinfo->modulus_length >> 3;
883			/* set the exponent (always 0x10001) */
884			buf = malloc(3);
885			if (!buf)
886				return SC_ERROR_OUT_OF_MEMORY;
887			buf[0] = 0x01;
888			buf[1] = 0x00;
889			buf[2] = 0x01;
890			rsa->exponent.data = buf;
891			rsa->exponent.len  = 3;
892	
893			pubkey->algorithm = SC_ALGORITHM_RSA;
894		} else
895			/* free public key */
896			free(gendat.modulus);
897	
898		return SC_SUCCESS;
899	}
900	
901	static int starcos_finalize_card(sc_card_t *card)
902	{
903		int       r;
904		sc_file_t tfile;
905		sc_path_t tpath;
906	
907		/* SELECT FILE MF */
908		sc_format_path("3F00", &tpath);
909		r = sc_select_file(card, &tpath, NULL);
910		if (r < 0)
911			return r;
912	
913		/* call CREATE END for the MF (ignore errors) */
914		tfile.type = SC_FILE_TYPE_DF;
915		tfile.id   = 0x3f00;
916		r = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_END, &tfile);
917		if (r < 0)
918			sc_log(card->ctx,  "failed to call CREATE END for the MF\n");
919		/* call CREATE END for the apps (pkcs15) DF */
920		tfile.type = SC_FILE_TYPE_DF;
921		tfile.id   = 0x5015;
922		r = sc_card_ctl(card, SC_CARDCTL_STARCOS_CREATE_END, &tfile);
923		if (r == SC_ERROR_NOT_ALLOWED)
924			/* card is already finalized */
925			return SC_SUCCESS;
926		return r;
927	}
928	
929	static struct sc_pkcs15init_operations sc_pkcs15init_starcos_operations = {
930		starcos_erase_card,
931		starcos_init_card,
932		starcos_create_dir,
933		NULL,				/* create_domain */
934		starcos_pin_reference,
935		starcos_create_pin,
936		starcos_key_reference,
937		starcos_create_key,
938		starcos_store_key,
939		starcos_generate_key,
940		NULL, NULL,			/* encode private/public key */
941		starcos_finalize_card,
942		NULL, 				/* delete_object */
943		NULL, NULL, NULL, NULL, NULL,	/* pkcs15init emulation */
944		NULL				/* sanity_check */
945	};
946	
947	struct sc_pkcs15init_operations *sc_pkcs15init_get_starcos_ops(void)
948	{
949		return &sc_pkcs15init_starcos_operations;
950	}
