255	
256	static int have_onepin(sc_profile_t *profile)
257	{
258		sc_pkcs15_auth_info_t sopin = {0};
259	
260		sc_profile_get_pin_info(profile, SC_PKCS15INIT_SO_PIN, &sopin);
261	
262		if (!(sopin.attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN))
263			return 1;
264		else
265			return 0;
266	}
267	
268	/* range of possible key ids for pins (note: the key id of the puk
269	 * is the key id of the pin plus one)
270	 */
271	#define STARCOS_MIN_LPIN_ID	0x83
272	#define STARCOS_MAX_LPIN_ID	0x8f
273	#define STARCOS_MIN_GPIN_ID	0x03
274	#define STARCOS_MAX_GPIN_ID	0x0f
275	static int starcos_pin_reference(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
276		sc_pkcs15_auth_info_t *auth_info)
277	{
278		int tmp;
279	
280		if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)
281			return SC_ERROR_OBJECT_NOT_VALID;
282	
283		tmp = auth_info->attrs.pin.reference;
284	
285		if (have_onepin(profile)) {
286			/* we have the onepin profile */
287			auth_info->attrs.pin.reference = STARCOS_SOPIN_GID;
288			return SC_SUCCESS;
289		}
290	
291		if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_LOCAL) {
292			/* use local KID */
293			/* SO-pin */
294			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN)
295				tmp = STARCOS_SOPIN_LID;
296			else {
297				if (tmp < STARCOS_MIN_LPIN_ID)
298					tmp = STARCOS_MIN_LPIN_ID;
299				if (!(tmp & 0x01))
300					/* odd KIDs for PINs and even KIDs for PUKs */
301					tmp++;
302				if (tmp > STARCOS_MAX_LPIN_ID)
303					return SC_ERROR_TOO_MANY_OBJECTS;
304			}
305		} else {
306			/* use global KID */
307			/* SO-pin */
308			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN)
309				tmp = STARCOS_SOPIN_GID;
310			else {
311				if (tmp < STARCOS_MIN_GPIN_ID)
312					tmp = STARCOS_MIN_GPIN_ID;
313				if (!(tmp & 0x01))
314					/* odd KIDs for PINs and even KIDs for PUKs */
315				tmp++;
316				if (tmp > STARCOS_MAX_GPIN_ID)
317					return SC_ERROR_TOO_MANY_OBJECTS;
318			}
319		}
320		auth_info->attrs.pin.reference = tmp;
321	
322		return SC_SUCCESS;
323	}
324	
325	/* About STARCOS_PINID2STATE
326	 * Starcos SPK 2.3 uses a state machine to control the access
327	 * to files or keys. This means that the access to a certain
328	 * object is granted if the current state (of either the current
329	 * DF or the MF) is =, <, >= or != a specified state (see
330	 * Starcos S 2.1 manual). To map the pkcs15 access control model
331	 *(one object is protected by one pin etc.) to the Starcos S 2.1
332	 * model the following approach is used:
333	 * the pin with the key id 3 (or 0x81) sets the global (or local)
334	 * state to 15 (note: 16 is the lowest initial state).
335	 * the pin with the key id 4 (or 0x82) is reserved for the PUK
336	 * the pin with the key id 5 (or 0x83) sets the global (or local)
337	 * state to 14.
338	 * ...
339	 * Note: the key id 1 and 2 (or local 0x81 and 0x82) is used for
340	 * the 'SO-pin' which sets the state to 0x01.
341	 * XXX: some card operations, like terminate card usage are only
342	 * possible in state 0x00
343	 *
344	 * Nils
345	 */
346	#define STARCOS_PINID2STATE(a)	(((a) == STARCOS_SOPIN_GID) ? STARCOS_SOPIN_STATE : (0x0f - ((0x0f & (a)) >> 1)))
347	
348	static int starcos_create_pin(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
349		sc_file_t *df, sc_pkcs15_object_t *pin_obj,
350		const unsigned char *pin, size_t pin_len,
351		const unsigned char *puk, size_t puk_len)
352	{
353		struct sc_card *card = p15card->card;
354		int	r, is_local, pin_id, tmp, need_finalize = 0;
355		size_t	akd;
356		sc_file_t            *tfile;
357		const sc_acl_entry_t *acl_entry;
358		sc_pkcs15_auth_info_t *auth_info = (sc_pkcs15_auth_info_t *) pin_obj->data;
359		sc_starcos_wkey_data  pin_d, puk_d;
360		u8		      tpin[8];
361	
362		if (!pin || !pin_len || pin_len > 8)
363			return SC_ERROR_INVALID_ARGUMENTS;
364	
365		if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)
366			return SC_ERROR_OBJECT_NOT_VALID;
367	
368		is_local = 0x80 & auth_info->attrs.pin.reference;
369		if (is_local)
370			r = sc_select_file(card, &df->path, NULL);
371		else
372			r = sc_select_file(card, &profile->mf_info->file->path, NULL);
373		if (r < 0)
374			return r;
375		/* get and verify sopin if necessary */
376		r = sc_profile_get_file(profile, "p15_isf", &tfile);
377	        if (r < 0)
378	                return r;
379		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
380		if (acl_entry->method != SC_AC_NONE) {
381			if ((auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN) || have_onepin(profile))
382				need_finalize = 1;
383			else
384				r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
385		}
386		sc_file_free(tfile);
387		if (r < 0)
388			return r;
389	
390		/* pad pin with 0 */
391		memset(tpin, 0, 8);
392		memcpy(tpin, pin, pin_len);
393	
394		/* write PIN */
395		tmp    = auth_info->tries_left;
396		pin_id = auth_info->attrs.pin.reference;
397	
398		pin_d.mode    = 0;	/* install */
399		pin_d.kid     = (u8) pin_id;
400		pin_d.key     = tpin;
401		pin_d.key_len = 8;
402		pin_d.key_header[0]  = pin_d.kid;
403		pin_d.key_header[1]  = 0;
404		pin_d.key_header[2]  = 8;
405		pin_d.key_header[3]  = STARCOS_AC_ALWAYS;
406		if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN)
407			pin_d.key_header[4] = STARCOS_SOPIN_STATE;
408		else
409			pin_d.key_header[4] = STARCOS_PINID2STATE(pin_id);
410		pin_d.key_header[5]  = STARCOS_AC_ALWAYS;
411		pin_d.key_header[6]  = ((0x0f & tmp) << 4) | (0x0f & tmp);
412		pin_d.key_header[7]  = 0x00;
413		pin_d.key_header[8]  = 0x00;
414		akd = auth_info->attrs.pin.min_length;
415		if (akd < 4)
416			akd = 4;
417		if (akd > 8)
418			akd = 8;
419		akd--;
420		akd |= 0x08;
421		pin_d.key_header[9]  = akd;	/* AKD: standard + every char != 0 +
422						 * pin min length */
423		pin_d.key_header[10] = 0x00;	/* never allow WRITE KEY    */
424		pin_d.key_header[11] = 0x81;	/* key attribute: akd + pin */
425		/* create/write PIN */
426		r = sc_card_ctl(card, SC_CARDCTL_STARCOS_WRITE_KEY, &pin_d);
427		if (r != SC_SUCCESS)
428			return r;
429	
430		if (puk && puk_len) {
431			sc_pkcs15_auth_info_t puk_info = {0};
432	
433			if (puk_len > 8)
434				return SC_ERROR_INVALID_ARGUMENTS;
435			memset(tpin, 0, 8);
436			memcpy(tpin, puk, puk_len);
437	
438			sc_profile_get_pin_info(profile, SC_PKCS15INIT_USER_PUK, &puk_info);
439			tmp = puk_info.tries_left;
440	
441			puk_d.mode    = 0;	/* install */
442			puk_d.kid     = (u8) pin_id + 1;
443			puk_d.key     = tpin;
444			puk_d.key_len = 8;
445			puk_d.key_header[0]  = puk_d.kid;
446			puk_d.key_header[1]  = 0;
447			puk_d.key_header[2]  = 8;
448			puk_d.key_header[3]  = STARCOS_AC_ALWAYS;
449			puk_d.key_header[4]  = ((pin_id & 0x1f) << 3) | 0x05;
450			puk_d.key_header[5]  = 0x01;
451			puk_d.key_header[6]  = ((0x0f & tmp) << 4) | (0x0f & tmp);
452			puk_d.key_header[7]  = 0x0;
453			puk_d.key_header[8]  = 0x0;
454			puk_d.key_header[9]  = 0x0;
455			puk_d.key_header[10] = 0x00;
456			puk_d.key_header[11] = 0x02;
457			/* create/write PUK */
458			r = sc_card_ctl(card, SC_CARDCTL_STARCOS_WRITE_KEY, &puk_d);
459			if (r != SC_SUCCESS)
460				return r;
461		}
462	
463		/* in case of a global pin: write dummy entry in df isf */
464		if (!is_local) {
465			r = sc_select_file(card, &df->path, NULL);
466			if (r < 0)
467				return r;
468			pin_d.key     = NULL;
469			pin_d.key_len = 0;
470			pin_d.key_header[1] = 0;
471			pin_d.key_header[2] = 0;
472			/* create/write dummy PIN */
473			r = sc_card_ctl(card, SC_CARDCTL_STARCOS_WRITE_KEY, &pin_d);
474			if (r != SC_SUCCESS)
475				return r;
476		}
477	
478		/* in case of a SOPIN: if AC WRITE KEY is protected by the
479		 * SOPIN, call starcos_finalize_card to activate the ACs  */
480		if (need_finalize)
481			 r = starcos_finalize_card(card);
482	
483		return r;
484	}
