	struct sc_pkcs15_pubkey *pubkey = NULL;
	int r, caller_supplied_id = 0;
	unsigned long algorithm = keygen_args->prkey_args.key.algorithm;

	LOG_FUNC_CALLED(ctx);

	memset(&pubkey_args, 0, sizeof(pubkey_args));

	/* check supported key size */
